function measurementsPage(){const actions=can('medicoes','create')?btn('Nova medição','newMeasurement',true):'';if(state.context&&D.measurements.find(m=>m.id===state.context))return measurementDetailPage(D.measurements.find(m=>m.id===state.context));const approved=sum(D.measurements.filter(m=>m.status==='aprovada'),m=>m.amount);const pending=sum(D.measurements.filter(m=>m.status!=='aprovada'),m=>m.amount);return pageHead('Medições','Boletins por contrato, competência, aprovação e saldo.',actions)+`<div class="kpi-grid"><div class="card kpi"><div class="kpi-label">APROVADO ACUMULADO</div><div class="kpi-value">${moneyM(approved)}</div></div><div class="card kpi"><div class="kpi-label">EM FLUXO</div><div class="kpi-value">${moneyM(pending)}</div></div><div class="card kpi"><div class="kpi-label">BOLETINS</div><div class="kpi-value">${D.measurements.length}</div></div><div class="card kpi"><div class="kpi-label">CONTRATOS MEDIDOS</div><div class="kpi-value">${new Set(D.measurements.map(m=>m.contract)).size}</div></div></div><div class="card section">${measurementsTable(D.measurements)}</div>`}
