function invoicesPage(){const actions=can('nfs','create')?btn('Nova NF','newInvoice',true):'';if(state.context&&D.invoices.find(n=>n.id===state.context))return invoiceDetailPage(D.invoices.find(n=>n.id===state.context));const total=sum(D.invoices,n=>n.amount),paid=sum(D.payments.filter(p=>p.status==='pago'),p=>p.amount),payable=Math.max(0,sum(D.invoices.filter(n=>['aprovada','paga'].includes(n.status)),n=>n.amount)-paid);return pageHead('Notas Fiscais','Documento fiscal ligado à origem do custo, aprovação e pagamento.',actions)+`<div class="kpi-grid"><div class="card kpi"><div class="kpi-label">VALOR FISCAL</div><div class="kpi-value">${moneyM(total)}</div></div><div class="card kpi"><div class="kpi-label">PAGO</div><div class="kpi-value">${moneyM(paid)}</div></div><div class="card kpi"><div class="kpi-label">A PAGAR APROVADO</div><div class="kpi-value">${moneyM(payable)}</div></div><div class="card kpi"><div class="kpi-label">DOCUMENTOS</div><div class="kpi-value">${D.invoices.length}</div></div></div><div class="card section"><div class="table-wrap"><table><thead><tr><th>NF</th><th>Fornecedor</th><th>Data</th><th>Origem</th><th>Valor</th><th>Pago</th><th>Status</th><th></th></tr></thead><tbody>${D.invoices.map(n=>{const p=invoicePaidAmount(n.id);return `<tr style="cursor:pointer" onclick="openInvoiceDetail('${n.id}')"><td><b>${h(n.number)}</b></td><td>${h(n.supplier)}</td><td>${dateBR(n.data||n.date)}</td><td>${h(n.source||'Direto')}</td><td>${money(n.amount)}</td><td>${money(p)}</td><td>${statusPill(n.status)}</td><td>${can('nfs','edit')?`<button onclick="event.stopPropagation();editInvoiceAction('${n.id}'); return false;" style="padding:2px 6px;font-size:12px;margin-right:4px">✏ Editar</button><button onclick="event.stopPropagation();deleteInvoiceAction('${n.id}'); return false;" style="padding:2px 6px;font-size:12px">✕ Remover</button>`:''}</td></tr>`}).join('')}</tbody></table></div></div>`}
