function burndownChart(){
  const rows=D.curveS;
  if(!rows.length)return empty('Sem dados de Curva S para Burndown.');
  const cols=rows.map(x=>{const planRem=100-num(x.planned);const realRem=x.actual!==null?100-num(x.actual):null;return `<div class="curve-col"><div class="curve-bars"><span class="curve-plan" style="height:${planRem}%" title="Restante planejado ${planRem.toFixed(1)}%"></span>${realRem!==null?`<span class="curve-real" style="height:${realRem}%" title="Restante real ${realRem.toFixed(1)}%"></span>`:''}</div><small>${h(x.period)}</small><b>${realRem!==null?realRem.toFixed(1)+'%':'—'}</b></div>`}).join('');
  return `<div class="curve-grid">${cols}</div><div class="legend"><span><i class="legend-plan"></i>Restante planejado</span><span><i class="legend-real"></i>Restante real</span></div>`;
}
function planningPage(){let actions='';if(can('planejamento','create')){if(state.planningTab==='cronograma')actions=btn('Nova atividade','newPlanActivity',true);if(state.planningTab==='semanal')actions=btn('Novo item semanal','newWeeklyPlan',true);if(state.planningTab==='quinzenal')actions=btn('Novo item quinzenal','newFortnightPlan',true);if(state.planningTab==='restricoes')actions=btn('Nova restrição','newRestriction',true)}const tb=tabs([{id:'cronograma',label:'Cronograma / Avanço'},{id:'semanal',label:'Semanal'},{id:'quinzenal',label:'Quinzenal'},{id:'restricoes',label:'Restrições'},{id:'curvas',label:'Curva S'}],state.planningTab,'planning');let body='';
  if(state.planningTab==='cronograma')body=`<div class="card section"><div class="table-wrap"><table><thead><tr><th>EAP</th><th>Atividade</th><th>Início</th><th>Fim</th><th>Responsável</th><th>Plan.</th><th>Real</th><th>Desvio</th><th>Crítica</th></tr></thead><tbody>${D.planning.map(p=>`<tr><td>${h(wbsName(p.wbs))}</td><td>${h(p.activity)}</td><td>${dateBR(p.start)}</td><td>${dateBR(p.end)}</td><td>${h(p.owner)}</td><td>${pct(p.planned)}</td><td>${pct(p.actual)}</td><td class="${p.actual<p.planned?'metric-negative':'metric-positive'}">${(p.actual-p.planned).toFixed(1)} p.p.</td><td>${p.critical?statusPill('Crítica'):statusPill('Normal')}</td></tr>`).join('')}</tbody></table></div></div>`;
  if(state.planningTab==='semanal')body=`<div class="kpi-grid"><div class="card kpi"><div class="kpi-label">PPC</div><div class="kpi-value">${pct(ppc())}</div></div><div class="card kpi"><div class="kpi-label">ITENS</div><div class="kpi-value">${D.weeklyPlan.length}</div></div><div class="card kpi"><div class="kpi-label">CONCLUÍDOS</div><div class="kpi-value">${D.weeklyPlan.filter(x=>x.status==='concluida').length}</div></div><div class="card kpi"><div class="kpi-label">EM ANDAMENTO</div><div class="kpi-value">${D.weeklyPlan.filter(x=>x.status==='em_andamento').length}</div></div></div><div class="card section"><table><thead><tr><th>EAP</th><th>Atividade</th><th>Responsável</th><th>Planejado</th><th>Real</th><th>Aderência</th><th>Status</th><th></th></tr></thead><tbody>${D.weeklyPlan.map(x=>`<tr><td>${h(wbsName(x.wbs))}</td><td>${h(x.activity)}</td><td>${h(x.owner)}</td><td>${h(x.plannedQty)} ${h(x.unit)}</td><td>${h(x.actualQty)} ${h(x.unit)}</td><td>${pct(x.plannedQty?x.actualQty/x.plannedQty*100:0)}</td><td>${statusPill(x.status)}</td><td>${can('planejamento','edit')&&x.status!=='concluida'?iconBtn('Concluir',`complete-week:${x.id}`):''}</td></tr>`).join('')}</tbody></table></div>`;
  if(state.planningTab==='quinzenal')body=`<div class="card section"><table><thead><tr><th>EAP</th><th>Entrega</th><th>Responsável</th><th>Prazo</th><th>Status</th><th></th></tr></thead><tbody>${D.fortnightPlan.map(x=>`<tr><td>${h(wbsName(x.wbs))}</td><td>${h(x.activity)}</td><td>${h(x.owner)}</td><td>${dateBR(x.due)}</td><td>${statusPill(x.status)}</td><td>${can('planejamento','edit')&&x.status!=='concluida'?iconBtn('Concluir',`complete-fortnight:${x.id}`):''}</td></tr>`).join('')}</tbody></table></div>`;
  if(state.planningTab==='restricoes')body=`<div class="card section"><table><thead><tr><th>ID</th><th>EAP</th><th>Restrição</th><th>Responsável</th><th>Prazo</th><th>Status</th><th></th></tr></thead><tbody>${D.restrictions.map(r=>`<tr><td>${h(r.id)}</td><td>${h(wbsName(r.wbs))}</td><td>${h(r.title)}</td><td>${h(r.owner)}</td><td>${dateBR(r.due)}</td><td>${statusPill(r.status)}</td><td>${can('planejamento','edit')&&r.status!=='concluida'?iconBtn('Resolver',`resolve-restriction:${r.id}`):''}</td></tr>`).join('')}</tbody></table></div>`;
  if(state.planningTab==='curvas')body=`<div class="card section"><h2>Curva S física</h2><div class="curve-grid">${D.curveS.map(x=>`<div class="curve-col"><div class="curve-bars"><span class="curve-plan" style="height:${num(x.planned)}%" title="Planejado ${x.planned}%"></span>${x.actual!==null?`<span class="curve-real" style="height:${num(x.actual)}%" title="Real ${x.actual}%"></span>`:''}</div><small>${h(x.period)}</small><b>${x.actual!==null?h(x.actual)+'%':'—'}</b></div>`).join('')}</div><div class="legend"><span><i class="legend-plan"></i>Planejado</span><span><i class="legend-real"></i>Real</span></div></div><div class="card section gap-top"><h2>Burn Down (escopo restante)</h2>${burndownChart()}</div>`;
  return pageHead('Planejamento','Cronograma de controle, lookahead, PPC, restrições e Curva S.',actions)+tb+body;
}

function cadastroPage(){const actions=can('cadastro','create')?btn('Novo cadastro','newCatalogRecord',true):'';const tb=tabs([{id:'atividades',label:'Atividades'},{id:'epis',label:'EPIs'},{id:'funcoes',label:'Funções'},{id:'fornecedores',label:'Fornecedores'},{id:'entregas',label:'Entregas EPI'},{id:'cbs',label:'CBS'}],state.cadastroTab,'cadastro');let body='';if(state.cadastroTab==='atividades')body=`<div class="card section"><table><thead><tr><th>Descrição</th><th>Unidade</th><th>Ativo</th></tr></thead><tbody>${D.activitiesCatalog.map(x=>`<tr><td>${h(x.description)}</td><td>${h(x.unit)}</td><td>${statusPill(x.active?'Ativo':'Inativo')}</td></tr>`).join('')}</tbody></table></div>`;if(state.cadastroTab==='epis')body=`<div class="card section"><table><thead><tr><th>EPI</th><th>CA</th><th>Validade uso</th><th>Status</th></tr></thead><tbody>${D.epis.map(x=>`<tr><td>${h(x.name)}</td><td>${h(x.ca)}</td><td>${h(x.validityDays)} dias</td><td>${statusPill(x.active?'Ativo':'Inativo')}</td></tr>`).join('')}</tbody></table></div>`;if(state.cadastroTab==='funcoes')body=`<div class="card section"><table><thead><tr><th>Função</th><th>Categoria</th><th>Giro viagem</th></tr></thead><tbody>${D.functionsCatalog.map(x=>`<tr><td>${h(x.name)}</td><td>${h(x.category)}</td><td>${h(x.travelDays)} dias</td></tr>`).join('')}</tbody></table></div>`;if(state.cadastroTab==='fornecedores')body=`<div class="card section"><table><thead><tr><th>Fornecedor</th><th>CNPJ</th><th>Especialidade</th><th>Status</th></tr></thead><tbody>${D.suppliers.map(x=>`<tr><td>${h(x.name)}</td><td>${h(x.cnpj)}</td><td>${h(x.specialty)}</td><td>${statusPill(x.active?'Ativo':'Inativo')}</td></tr>`).join('')}</tbody></table></div>`;if(state.cadastroTab==='cbs')body=`<div class="card section"><table><thead><tr><th>Código</th><th>Descrição</th></tr></thead><tbody>${D.cbs.map(x=>`<tr><td><b>${h(x.code)}</b></td><td>${h(x.name)}</td></tr>`).join('')}</tbody></table></div>`;if(state.cadastroTab==='entregas')body=`<div class="card section"><table><thead><tr><th>Data</th><th>Colaborador</th><th>EPI</th><th>Qtd.</th><th>Motivo</th><th>Assinatura</th></tr></thead><tbody>${D.epiDeliveries.map(x=>`<tr><td>${dateBR(x.date)}</td><td>${h(D.people.find(p=>p.id===x.person)?.name||x.person)}</td><td>${h(D.epis.find(e=>e.id===x.epi)?.name||x.epi)}</td><td>${h(x.qty)}</td><td>${h(x.reason)}</td><td>${statusPill(x.signed?'OK':'Pendente')}</td></tr>`).join('')}</tbody></table></div>`;return pageHead('Cadastro','Cadastros locais e catálogos corporativos controlados.',actions)+tb+body}


function alertsPage(){return pageHead('Alertas','Prazos, desvios, vencimentos e riscos que exigem atenção.')+`<div class="grid-3">${D.alerts.map(a=>`<div class="card section ${a.read?'dimmed':''}"><div class="card-title-line"><h3>${h(a.title)}</h3>${statusPill(a.severity)}</div><p class="muted small">${h(a.detail)}</p>${can('alertas','edit')?btn(a.read?'Marcar não lido':'Marcar lido',`alert-${a.id}`):''}</div>`).join('')}</div>`}
function documentsPage(){const actions=can('documentos','create')?btn('Novo documento','newDocument',true):'';if(state.context&&D.documents.find(d=>d.id===state.context))return documentDetailPage(D.documents.find(d=>d.id===state.context));return pageHead('Documentos','GED com código, disciplina, revisão, status, notas e histórico.',actions)+`<div class="card section"><div class="table-wrap"><table><thead><tr><th>Título</th><th>Categoria</th><th>URL/Arquivo</th><th>Data criação</th><th>Status</th><th></th></tr></thead><tbody>${D.documents.map(d=>{const notes=D.documentNotes.filter(n=>n.document===d.id);return `<tr style="cursor:pointer" onclick="openDocumentDetail('${d.id}')"><td><b>${h(d.titulo)}</b></td><td>${h(d.categoria)}</td><td>${h(d.arquivo_nome||d.url?.split('/').pop()||'—')}</td><td>${dateBR(d.criado_em)}</td><td>${statusPill('active')}</td><td>${can('documentos','edit')?`<button onclick="event.stopPropagation();editDocumentAction('${d.id}'); return false;" style="padding:2px 6px;font-size:12px;margin-right:4px">✏ Editar</button><button onclick="event.stopPropagation();deleteDocumentAction('${d.id}'); return false;" style="padding:2px 6px;font-size:12px">✕ Remover</button>`:''}</td></tr>`}).join('')}</tbody></table></div></div>`}
function openDocumentDetail(id){state.context=id;renderAll()}
function editDocumentAction(id){state.editingDocument=id;modalDocument(id)}
function deleteDocumentAction(id){if(confirm('Confirmar exclusão do documento?')){D.documents=D.documents.filter(d=>d.id!==id);D.documentNotes=D.documentNotes.filter(n=>n.document!==id);state.context=null;toast('Documento removido.');renderAll()}}
function documentDetailPage(d){const notes=D.documentNotes.filter(n=>n.document===d.id);const actions=can('documentos','edit')?`<button onclick="event.stopPropagation();editDocumentAction('${d.id}')" class="btn btn-primary">✏ Editar</button><button onclick="event.stopPropagation();deleteDocumentAction('${d.id}')" class="btn btn-danger">✕ Excluir</button>`:'';return pageHead('Documento',d.titulo,actions)+`<div class="grid-2"><div class="card section"><h2>Dados do documento</h2>${financialList([['Título',d.titulo],['Categoria',d.categoria],['Arquivo',d.arquivo_nome||'—'],['URL',d.url?`<a href="${h(d.url)}" target="_blank">Abrir</a>`:'—'],['Valor orçado',d.valor_orcamento?money(d.valor_orcamento):'—'],['Data cronograma',dateBR(d.data_cronograma)]])}</div><div class="card section"><h2>Auditoria</h2>${financialList([['Criado em',d.criado_em?new Date(d.criado_em).toLocaleString('pt-BR'):'—'],['Atualizado em',d.atualizado_em?new Date(d.atualizado_em).toLocaleString('pt-BR'):'—'],['ID legado',d.id_legado||'—']])}</div></div><div class="card section gap-top"><h2>Notas ${notes.length?`(${notes.length})`:''}</h2>${notes.length?`<div class="notes-list">${notes.map(n=>`<div class="note-item"><div class="note-head"><b>${h(n.autor)}</b> · ${new Date(n.criado_em).toLocaleString('pt-BR')}${can('documentos','edit')?`<button onclick="event.stopPropagation();deleteDocumentNote('${n.id}'); return false;" style="float:right;padding:2px 4px;font-size:11px;">×</button>`:''}</div><div class="note-text">${h(n.texto)}</div></div>`).join('')}</div>`:empty('Sem notas neste documento.')}<div class="actions gap-top">${can('documentos','edit')?btn('+ Adicionar nota','addDocumentNote-'+d.id,'','','style="margin-top:8px"'):''}</div></div><div class="actions gap-top"><button onclick="state.context=null;renderAll()" class="btn">← Voltar</button></div>`}
function equipmentPage(){const actions=can('equipamentos','create')?`${btn('Novo equipamento','newEquipment',true)}${btn('Programar manutenção','newMaintenance')}`:'';if(state.context&&D.equipment.find(e=>e.id===state.context))return equipmentDetailPage(D.equipment.find(e=>e.id===state.context));const equipRows=D.equipment.map(e=>`<tr style="cursor:pointer" onclick="openEquipmentDetail('${e.id}')"><td><b>${h(e.prefix)}</b></td><td>${h(e.type)}</td><td>${h(e.owner)}</td><td>${h(e.supplier||'—')}</td><td>${pct(e.availability)}</td><td>${pct(e.utilization)}</td><td>${statusPill(e.status)}</td><td>${can('equipamentos','edit')?`<button onclick="event.stopPropagation();editEquipmentAction('${e.id}'); return false;" style="padding:2px 6px;font-size:12px;margin-right:4px">✏ Editar</button><button onclick="event.stopPropagation();deleteEquipmentAction('${e.id}'); return false;" style="padding:2px 6px;font-size:12px">✕ Remover</button>`:''}</td></tr>`).join('');return pageHead('Equipamentos','Frota, disponibilidade, utilização e manutenção.',actions)+`<div class="grid-2"><div class="card section"><h2>Frota</h2><table><thead><tr><th>Prefixo</th><th>Equipamento</th><th>Propriedade</th><th>Fornecedor</th><th>Disp.</th><th>Util.</th><th>Status</th><th></th></tr></thead><tbody>${equipRows}</tbody></table></div><div class="card section"><h2>Manutenção</h2><table><thead><tr><th>Data</th><th>Equipamento</th><th>Tipo</th><th>Descrição</th><th>Status</th></tr></thead><tbody>${D.maintenance.map(m=>{const e=D.equipment.find(x=>x.id===m.equipment);return `<tr><td>${dateBR(m.date)}</td><td>${h(e?.prefix||m.equipment)}</td><td>${h(m.type)}</td><td>${h(m.description)}</td><td>${statusPill(m.status)}</td></tr>`}).join('')||'<tr><td colspan="5">Sem manutenções.</td></tr>'}</tbody></table></div></div>`}
