function equipmentDetailPage(e){const allocs=D.equipmentAllocations.filter(a=>a.equipment===e.id);const maint=D.maintenance.filter(m=>m.equipment===e.id).sort((a,b)=>b.date.localeCompare(a.date));const actions=can('equipamentos','edit')?`<button onclick="event.stopPropagation();editEquipmentAction('${e.id}')" class="btn btn-primary">✏ Editar</button><button onclick="event.stopPropagation();deleteEquipmentAction('${e.id}')" class="btn btn-danger">✕ Excluir</button>`:'';return pageHead('Equipamento',e.prefix,actions)+`<div class="grid-2"><div class="card section"><h2>🚗 Dados técnicos</h2>${financialList([['Prefixo',e.prefix],['Tipo',e.type],['Marca',e.brand||'—'],['Modelo',e.model||'—'],['Placa',e.plate||'—'],['Ano',e.year||'—'],['Categoria',e.category||'—']])}</div><div class="card section"><h2>📊 Operacional</h2>${financialList([['Propriedade',e.owner],['Fornecedor',e.supplier||'—'],['Disponibilidade',`${e.availability}%`],['Utilização',`${e.utilization}%`],['Status',statusPill(e.status)],['Ativo',e.active?'Sim':'Não']])}</div></div><div class="grid-2 gap-top"><div class="card section"><h2>📍 Alocações</h2>${allocs.length?`<table><thead><tr><th>Obra</th><th>Início</th><th>Fim</th><th>Status</th></tr></thead><tbody>${allocs.map(a=>`<tr><td>${h(a.workId)}</td><td>${dateBR(a.dateIn)}</td><td>${a.dateOut?dateBR(a.dateOut):'—'}</td><td>${statusPill(a.status)}</td></tr>`).join('')}</tbody></table>`:empty('Sem alocações registradas.')}</div><div class="card section"><h2>🔧 Manutenção</h2>${maint.length?`<table><thead><tr><th>Data</th><th>Tipo</th><th>Descrição</th><th>Status</th></tr></thead><tbody>${maint.map(m=>`<tr><td>${dateBR(m.date)}</td><td>${h(m.type)}</td><td>${h(m.description)}</td><td>${statusPill(m.status)}</td></tr>`).join('')}</tbody></table>`:empty('Sem manutenções registradas.')}</div></div><div class="actions gap-top"><button onclick="state.context=null;renderAll()" class="btn">← Voltar</button></div>`}
function meetingsPage(){const actions=can('reunioes','create')?btn('Nova reunião','newMeeting',true):'';if(state.context&&D.meetings.find(m=>m.id===state.context))return meetingDetailPage(D.meetings.find(m=>m.id===state.context));return pageHead('Reuniões','Pauta, ata, decisões, participantes e tarefas vinculadas.',actions)+`<div class="card section"><div class="table-wrap"><table><thead><tr><th>Data</th><th>Título</th><th>Hora</th><th>Local</th><th>Status</th><th></th></tr></thead><tbody>${D.meetings.map(m=>`<tr style="cursor:pointer" onclick="openMeetingDetail('${m.id}')"><td>${dateBR(m.date)}</td><td><b>${h(m.titulo)}</b></td><td>${m.hora_inicio||'—'}</td><td>${h(m.local||'—')}</td><td>${statusPill(m.status)}</td><td>${can('reunioes','edit')?`<button onclick="event.stopPropagation();editMeetingAction('${m.id}'); return false;" style="padding:2px 6px;font-size:12px;margin-right:4px">✏ Editar</button><button onclick="event.stopPropagation();deleteMeetingAction('${m.id}'); return false;" style="padding:2px 6px;font-size:12px">✕ Remover</button>`:''}</td></tr>`).join('')}</tbody></table></div></div>`}
