function meetingDetailPage(m){const participants=m.participants||[];const topics=m.topics||[];const notes=D.meetingNotes.filter(n=>n.reuniao_id===m.id);const actions=can('reunioes','edit')?`<button onclick="event.stopPropagation();editMeetingAction('${m.id}')" class="btn btn-primary">✏ Editar</button><button onclick="event.stopPropagation();deleteMeetingAction('${m.id}')" class="btn btn-danger">✕ Excluir</button>`:'';return pageHead('Reunião',m.titulo,actions)+`<div class="grid-2"><div class="card section"><h2>Dados da reunião</h2>${financialList([['Data',dateBR(m.date)],['Hora início',m.hora_inicio||'—'],['Hora fim',m.hora_fim||'—'],['Local',m.local||'—'],['Status',statusPill(m.status)]])}</div><div class="card section"><h2>Auditoria</h2>${financialList([['Criado em',m.criado_em?new Date(m.criado_em).toLocaleString('pt-BR'):'—'],['Atualizado em',m.atualizado_em?new Date(m.atualizado_em).toLocaleString('pt-BR'):'—'],['ID legado',m.id_legado||'—']])}</div></div><div class="grid-2 gap-top"><div class="card section"><h2>Participantes ${participants.length}</h2>${participants.length?`<table><thead><tr><th>Nome</th><th>Cargo</th><th>Responsável</th></tr></thead><tbody>${participants.map(p=>`<tr><td>${h(p.nome)}</td><td>${h(p.cargo)}</td><td>${p.responsavel?'Sim':'—'}</td></tr>`).join('')}</tbody></table>`:empty('Sem participantes registrados.')}</div><div class="card section"><h2>Tópicos ${topics.length}</h2>${topics.length?`<table><thead><tr><th>#</th><th>Título</th><th>Decisão</th></tr></thead><tbody>${topics.map(t=>`<tr><td>${t.ordem}</td><td><b>${h(t.titulo)}</b></td><td>${h(t.decisao||'—')}</td></tr>`).join('')}</tbody></table>`:empty('Sem tópicos registrados.')}</div></div><div class="card section gap-top"><h2>Notas ${notes.length?`(${notes.length})`:''}</h2>${notes.length?`<div class="notes-list">${notes.map(n=>`<div class="note-item"><div class="note-head"><b>${h(n.autor)}</b> · ${new Date(n.criado_em).toLocaleString('pt-BR')}${can('reunioes','edit')?`<button onclick="event.stopPropagation();deleteMeetingNote('${n.id}'); return false;" style="float:right;padding:2px 4px;font-size:11px;">×</button>`:''}</div><div class="note-text">${h(n.texto)}</div></div>`).join('')}</div>`:empty('Sem notas nesta reunião.')}<div class="actions gap-top">${can('reunioes','edit')?btn('+ Adicionar nota','addMeetingNote-'+m.id,'','','style="margin-top:8px"'):''}</div></div><div class="actions gap-top"><button onclick="state.context=null;renderAll()" class="btn">← Voltar</button></div>`}
function occurrencesPage(){const actions=can('ocorrencias','create')?btn('Nova ocorrência','newOccurrence',true):'';if(state.context&&D.occurrences.find(o=>o.id===state.context))return occurrenceDetailPage(D.occurrences.find(o=>o.id===state.context));const occRows=D.occurrences.map(o=>`<tr style="cursor:pointer" onclick="openOccurrenceDetail('${o.id}')"><td>${dateBR(o.date)}</td><td>${h(o.type)}</td><td>${statusPill(o.severity)}</td><td>${h(o.description)}</td><td>${h(o.action)}</td><td>${h(o.owner||'—')}</td><td>${can('ocorrencias','edit')?`<button onclick="event.stopPropagation();editOccurrenceAction('${o.id}'); return false;" style="padding:2px 6px;font-size:12px;margin-right:4px">✏ Editar</button><button onclick="event.stopPropagation();deleteOccurrenceAction('${o.id}'); return false;" style="padding:2px 6px;font-size:12px">✕ Remover</button>`:''}</td></tr>`).join('');return pageHead('Ocorrências','Registro operacional, segurança, qualidade e ação tomada.',actions)+`<div class="card section"><table><thead><tr><th>Data</th><th>Tipo</th><th>Gravidade</th><th>Descrição</th><th>Ação</th><th>Responsável</th><th></th></tr></thead><tbody>${occRows}</tbody></table></div>`}
