function deleteOccurrenceAction(id){if(confirm('Confirmar exclusão da ocorrência?')){D.occurrences=D.occurrences.filter(o=>o.id!==id);state.context=null;toast('Ocorrência removida.');renderAll()}}
function occurrenceDetailPage(o){const person=D.people.find(p=>p.id===o.contractId);const actions=can('ocorrencias','edit')?`<button onclick="event.stopPropagation();editOccurrenceAction('${o.id}')" class="btn btn-primary">✏ Editar</button><button onclick="event.stopPropagation();deleteOccurrenceAction('${o.id}')" class="btn btn-danger">✕ Excluir</button>`:'';return pageHead('Ocorrência',`${o.type} - ${dateBR(o.date)}`,actions)+`<div class="grid-2"><div class="card section"><h2>📋 Ocorrência</h2>${financialList([['Tipo',o.type],['Data',dateBR(o.date)],['Gravidade',statusPill(o.severity)],['Registrado por',o.registeredBy||'—'],['Vinculado a',person?person.name:'—'],['RDO',o.rdoId||'—']])}</div><div class="card section"><h2>📝 Descrição</h2><p>${h(o.description)}</p><h3 style="margin-top:12px">Ação Tomada</h3><p>${h(o.action||'—')}</p>${o.daysAway>0?`<p style="color:#d32f2f;font-weight:bold">Dias de afastamento: ${o.daysAway}</p>`:''}</div></div><div class="actions gap-top"><button onclick="state.context=null;renderAll()" class="btn">← Voltar</button></div>`}
function tasksPage(){const actions=can('tarefas','create')?btn('Nova tarefa','newTask',true):'';if(state.context&&D.tasks.find(t=>t.id===state.context))return taskDetailPage(D.tasks.find(t=>t.id===state.context));const cols=[['aberta','A fazer'],['em_andamento','Fazendo'],['concluida','Concluído']];return pageHead('Tarefas','Kanban de pendências com responsável, prazo, prioridade e origem.',actions)+`<div class="kanban">${cols.map(([status,label],idx)=>`<div class="kanban-col"><div class="kanban-head"><b>${h(label)}</b><span>${D.tasks.filter(t=>t.status===status).length}</span></div>${D.tasks.filter(t=>t.status===status).map(t=>`<div class="task-card" style="cursor:pointer" onclick="openTaskDetail('${t.id}')"><div class="task-title">${h(t.subject)}</div><div class="task-meta">${h(t.owner)} · ${dateBR(t.due)}</div><div class="task-foot">${statusPill(t.priority)}<div>${idx>0&&can('tarefas','edit')?iconBtn('←',`task-left:${t.id}`):''}${idx<2&&can('tarefas','edit')?iconBtn('→',`task-right:${t.id}`):''}${can('tarefas','delete')?iconBtn('×',`task-delete:${t.id}`):''}</div></div></div>`).join('')||empty('Sem tarefas.')}</div>`).join('')}</div>`}
