function taskDetailPage(t){const actions=can('tarefas','edit')?`<button onclick="event.stopPropagation();editTaskAction('${t.id}')" class="btn btn-primary">✏ Editar</button><button onclick="event.stopPropagation();deleteTaskAction('${t.id}')" class="btn btn-danger">✕ Excluir</button>`:'';return pageHead('Tarefa',t.subject,actions)+`<div class="grid-2"><div class="card section"><h2>📋 Descrição</h2><p>${h(t.description||'—')}</p>${financialList([['Criador',t.creator||'—'],['Responsável',t.owner],['Setor',t.sector||'—'],['Origem',t.origin||'—']])}</div><div class="card section"><h2>📅 Prazos</h2>${financialList([['Lançamento',dateBR(t.launchDate)],['Previsão',dateBR(t.due)],['Prioridade',statusPill(t.priority)],['Status',statusPill(t.status)],['Concluído em',t.completedAt?new Date(t.completedAt).toLocaleString('pt-BR'):'—']])}</div></div><div class="actions gap-top"><button onclick="state.context=null;renderAll()" class="btn">← Voltar</button></div>`}
function workforcePage(){const total=sum(D.workforce,x=>x.total);const actions=can('efetivo','create')?btn('Novo colaborador','newPerson',true):'';if(state.context&&D.people.find(p=>p.id===state.context))return personDetailPage(D.people.find(p=>p.id===state.context));const peopleRows=D.people.map(p=>`<tr style="cursor:pointer" onclick="openPersonDetail('${p.id}')"><td><b>${h(p.name)}</b></td><td>${h(p.company)}</td><td>${h(p.function)}</td><td>${h(p.type)}</td><td>${statusPill(p.status)}</td><td>${can('efetivo','edit')?`<button onclick="event.stopPropagation();editPersonAction('${p.id}'); return false;" style="padding:2px 6px;font-size:12px;margin-right:4px">✏ Editar</button><button onclick="event.stopPropagation();deletePersonAction('${p.id}'); return false;" style="padding:2px 6px;font-size:12px">✕ Remover</button>`:''}</td></tr>`).join('');return pageHead('Efetivo','Próprios, terceiros, contratos e composição por empresa.',actions)+`<div class="kpi-grid"><div class="card kpi"><div class="kpi-label">EFETIVO ATUAL</div><div class="kpi-value">${total}</div></div><div class="card kpi"><div class="kpi-label">PRÓPRIOS</div><div class="kpi-value">${sum(D.workforce,x=>x.own)}</div></div><div class="card kpi"><div class="kpi-label">TERCEIROS</div><div class="kpi-value">${sum(D.workforce,x=>x.third)}</div></div><div class="card kpi"><div class="kpi-label">EMPRESAS</div><div class="kpi-value">${D.workforce.length}</div></div></div><div class="grid-2"><div class="card section"><h2>Composição</h2><table><thead><tr><th>Empresa</th><th>Próprios</th><th>Terceiros</th><th>Total</th></tr></thead><tbody>${D.workforce.map(w=>`<tr><td>${h(w.company)}</td><td>${h(w.own)}</td><td>${h(w.third)}</td><td><b>${h(w.total)}</b></td></tr>`).join('')}</tbody></table></div><div class="card section"><h2>Cadastros individuais</h2><table><thead><tr><th>Nome</th><th>Empresa</th><th>Função</th><th>Tipo</th><th>Status</th><th></th></tr></thead><tbody>${peopleRows}</tbody></table></div></div>`}
