function personDetailPage(p){const fh=D.functionHistory.filter(f=>f.person===p.id).sort((a,b)=>b.startDate.localeCompare(a.startDate));const epis=D.epiDeliveries.filter(e=>e.person===p.id);const actions=can('efetivo','edit')?`<button onclick="event.stopPropagation();editPersonAction('${p.id}')" class="btn btn-primary">✏ Editar</button><button onclick="event.stopPropagation();deletePersonAction('${p.id}')" class="btn btn-danger">✕ Excluir</button>`:'';return pageHead('Colaborador',p.name,actions)+`<div class="grid-2"><div class="card section"><h2>📋 Dados pessoais</h2>${financialList([['Nome',p.name],['CPF',p.cpf||'—'],['CTPS',p.ctps||'—'],['PIS',p.pis||'—'],['CNH',p.cnh||'—'],['Data de nascimento',p.birthDate?dateBR(p.birthDate):'—'],['Telefone',p.phone||'—'],['Endereço',p.address||'—']])}</div><div class="card section"><h2>🏢 Vínculo funcional</h2>${financialList([['Empresa',p.company],['Tipo',p.type],['Função atual',p.function],['Admissão',dateBR(p.admission)],['Desligamento',p.discharge?dateBR(p.discharge):'—'],['Status',statusPill(p.status)]])}</div></div><div class="grid-2 gap-top"><div class="card section"><h2>📅 Histórico de funções</h2>${fh.length?`<table><thead><tr><th>Função</th><th>Desde</th><th>Até</th><th>Status</th></tr></thead><tbody>${fh.map(f=>`<tr><td>${h(f.function)}</td><td>${dateBR(f.startDate)}</td><td>${f.endDate?dateBR(f.endDate):'—'}</td><td>${statusPill(f.status)}</td></tr>`).join('')}</tbody></table>`:empty('Sem histórico de mudanças.')}</div><div class="card section"><h2>🦺 Entregas de EPI</h2>${epis.length?`<table><thead><tr><th>EPI</th><th>Data</th><th>Qtd</th><th>Motivo</th></tr></thead><tbody>${epis.map(e=>{const epi=D.epis.find(x=>x.id===e.epi);return`<tr><td>${h(epi?.name||'—')}</td><td>${dateBR(e.date)}</td><td>${e.qty}</td><td>${e.reason.replace('_',' ')}</td></tr>`}).join('')}</tbody></table>`:empty('Sem entregas registradas.')}</div></div><div class="actions gap-top"><button onclick="state.context=null;renderAll()" class="btn">← Voltar</button></div>`}

function rdoDefaultClimate(r){
  const cond=(r.condition||'praticavel')==='impraticavel'?'impraticavel':'praticavel';
  const norm=v=>String(v||'').toLowerCase().replace('sol','sol').replace('nublado','nublado').replace('chuva','chuva');
  return {
    madrugada:{tempo:'',chuvaMm:0,operacao:cond},
    manha:{tempo:norm(r.weatherMorning||r.weather),chuvaMm:0,operacao:cond},
    tarde:{tempo:norm(r.weatherAfternoon||r.weather),chuvaMm:0,operacao:cond},
    noite:{tempo:'',chuvaMm:0,operacao:cond}
  };
}
function rdoNormalize(r){
  if(!r)return r;
  r.status=r.status||'rascunho';
  r.location=r.location||{local:'',description:''};
  r.climate=r.climate||rdoDefaultClimate(r);
  for(const p of ['madrugada','manha','tarde','noite'])r.climate[p]=Object.assign({tempo:'',chuvaMm:0,operacao:'praticavel'},r.climate[p]||{});
  r.journey=r.journey||{start:'07:00',lunchStart:'12:00',lunchEnd:'13:00',end:'17:00'};
  r.dssDetail=r.dssDetail||{time:'07:00',instructor:'',theme:r.dss||''};
  r.attendance=r.attendance||[];
  r.equipmentUse=r.equipmentUse||[];
  r.lightVehiclesUse=r.lightVehiclesUse||[];
  r.activities=r.activities||[];
  if(!r.activities.length&&r.progress)r.activities.push({id:uid('RAT'),catalogId:'',description:r.progress,location:'',qty:0,unit:'',status:'andamento',wbs:''});
  r.pausedActivities=r.pausedActivities||[];
  r.safetyEvents=r.safetyEvents||[];
  r.environmentEvents=r.environmentEvents||[];
  r.photos=r.photos||[];
  r.responsible=r.responsible||'';
  r.signatures=r.signatures||{};
  r.notes=r.notes||'';
  r.paradosReasons=r.paradosReasons||{};
  return r;
}
D.rdos.forEach(rdoNormalize);
function rdoSelected(){return rdoNormalize(D.rdos.find(x=>x.id===state.context)||D.rdos.slice().sort((a,b)=>b.date.localeCompare(a.date))[0]||null)}
function rdoPerson(id){return D.people.find(p=>p.id===id)}
function rdoEquipment(id){return D.equipment.find(e=>e.id===id)}
function rdoAttendanceCount(r){return r.attendance?.length?r.attendance.filter(x=>x.status==='presente').length:num(r.workforce)}
function rdoEquipCount(r){return r.equipmentUse?.length?r.equipmentUse.filter(x=>x.active).length:num(r.equipment)}
function rdoRain(r){return sum(Object.values(r.climate||{}),x=>x.chuvaMm)}
function rdoWeatherLabel(r,p='manha'){const x=r.climate?.[p];return x?.tempo?({sol:'Sol',nublado:'Nublado',chuva:'Chuva'}[x.tempo]||x.tempo):(p==='manha'?(r.weatherMorning||r.weather):(r.weatherAfternoon||r.weather))||'—'}
const paradosReasonOptions=['Chuva','Doença','Férias','Folga','Falta','Manutenção','Não necessário','Sem operação'];
function rdoTable(list){return `<div class="table-wrap"><table><thead><tr><th>RDO</th><th>Data</th><th>Clima</th><th>Chuva</th><th>Efetivo</th><th>Equip.</th><th>Atividades</th><th>Status</th></tr></thead><tbody>${list.slice().sort((a,b)=>b.date.localeCompare(a.date)).map(x=>{const r=rdoNormalize(x);return `<tr class="clickable-row" data-rdo="${h(r.id)}"><td><b>${String(r.number).padStart(3,'0')}</b></td><td>${dateBR(r.date)}</td><td>${h(rdoWeatherLabel(r,'manha'))} / ${h(rdoWeatherLabel(r,'tarde'))}</td><td>${rdoRain(r).toLocaleString('pt-BR',{maximumFractionDigits:1})} mm</td><td>${rdoAttendanceCount(r)}</td><td>${rdoEquipCount(r)}</td><td>${r.activities.length}</td><td>${statusPill(r.status)}</td></tr>`}).join('')}</tbody></table></div>`}
function rdoPersonOptions(value=''){return `<option value="">— Selecionar —</option>`+D.people.filter(p=>p.status==='ativo').map(p=>option(p.id,`${p.name} · ${p.function}`,p.id===value)).join('')}
function rdoWbsOptions(value=''){return `<option value="">— Sem EAP —</option>`+D.wbs.map(w=>option(w.id,`${w.code} ${w.name}`,w.id===value)).join('')}
function rdoClimateCard(r,p,label){const x=r.climate[p];return `<div class="rdo-section"><div class="rdo-section-title">${h(label)}</div><div style="display:grid;grid-template-columns:1fr 1fr 1fr;gap:8px"><div class="rdo-field"><label>Tempo</label><select data-rdo-field="climate.${p}.tempo"><option value="">—</option>${option('sol','☀ Sol',x.tempo==='sol')}${option('nublado','☁ Nublado',x.tempo==='nublado')}${option('chuva','🌧 Chuva',x.tempo==='chuva')}</select></div><div class="rdo-field"><label>Chuva (mm)</label><input type="number" step="0.1" min="0" value="${h(x.chuvaMm)}" data-rdo-field="climate.${p}.chuvaMm"></div><div class="rdo-field"><label>Operação</label><select data-rdo-field="climate.${p}.operacao">${option('praticavel','✅ Operação',x.operacao==='praticavel')}${option('impraticavel','⛔ Sem operação',x.operacao==='impraticavel')}</select></div></div></div>`}
function rdoAttendanceEditor(r){const selected=state.rdoSelectedPeople||new Set();const allPeople=D.people.filter(p=>p.status==='ativo');const selectedPeople=allPeople.filter(p=>selected.has(p.id));const paradosPeople=allPeople.filter(p=>!selected.has(p.id));let html='';if(selectedPeople.length>0){const rows=selectedPeople.map(p=>{let a=r.attendance.find(x=>x.person===p.id);if(!a)a={person:p.id,status:'falta',normal:0,extra:0,obs:''};return `<tr><td><b>${h(p.name)}</b><div class="muted small">${h(p.company)} · ${h(p.function)}</div></td><td><select data-rdo-att="${h(p.id)}" data-key="status">${['presente','falta','falta_justificada','atestado','ferias','folga'].map(v=>option(v,v.replace('_',' '),a.status===v)).join('')}</select></td><td><input type="number" step="0.5" min="0" value="${h(a.normal)}" data-rdo-att="${h(p.id)}" data-key="normal"></td><td><input type="number" step="0.5" min="0" value="${h(a.extra)}" data-rdo-att="${h(p.id)}" data-key="extra"></td><td><input value="${h(a.obs||'')}" data-rdo-att="${h(p.id)}" data-key="obs"></td></tr>`}).join('');html+=`<div class="table-wrap"><table class="rdo-detail-table"><thead><tr><th>Colaborador</th><th>Situação</th><th>HN</th><th>HE</th><th>Observação</th></tr></thead><tbody>${rows}</tbody></table></div>`}if(paradosPeople.length>0){html+=`<div class="rdo-parados-section"><div class="rdo-section-title">⏸ Parados (não selecionados)</div><div class="list">${paradosPeople.map(p=>`<div class="rdo-parados-item"><div><b>${h(p.name)}</b><div class="muted">${h(p.company)} · ${h(p.function)}</div></div><div style="flex:1"><select data-rdo-parado="people:${h(p.id)}" style="width:100%"><option value="">— Motivo —</option>${paradosReasonOptions.map(opt=>`<option value="${h(opt)}" ${r.paradosReasons?.['people:'+p.id]===opt?'selected':''}>${h(opt)}</option>`).join('')}</select></div></div>`).join('')}</div></div>`}return html||`<div class="rdo-empty">Clique em + para selecionar efetivo.</div>`}
function rdoEquipmentEditor(r){const selected=state.rdoSelectedEquipment||new Set();const allEquip=D.equipment;const selectedEquip=allEquip.filter(e=>selected.has(e.id));const paradosEquip=allEquip.filter(e=>!selected.has(e.id));let html='';if(selectedEquip.length>0){const rows=selectedEquip.map(e=>{let u=r.equipmentUse.find(x=>x.equipment===e.id);if(!u)u={equipment:e.id,active:false,operator:'',status:'operando',hoursOperating:0,hoursStopped:0,reason:'',horimeterStart:'',horimeterEnd:''};return `<tr><td><label class="check-label"><input type="checkbox" ${u.active?'checked':''} data-rdo-equip="${h(e.id)}" data-key="active"> <b>${h(e.prefix)}</b> · ${h(e.type)}</label></td><td><select data-rdo-equip="${h(e.id)}" data-key="operator">${rdoPersonOptions(u.operator)}</select></td><td><select data-rdo-equip="${h(e.id)}" data-key="status">${option('operando','Operando',u.status==='operando')}${option('parado','Parado',u.status==='parado')}${option('manutencao','Manutenção',u.status==='manutencao')}</select></td><td><input type="number" step="0.1" min="0" value="${h(u.hoursOperating)}" data-rdo-equip="${h(e.id)}" data-key="hoursOperating"></td><td><input type="number" step="0.1" min="0" value="${h(u.hoursStopped)}" data-rdo-equip="${h(e.id)}" data-key="hoursStopped"></td><td><input type="number" step="0.1" value="${h(u.horimeterStart||'')}" data-rdo-equip="${h(e.id)}" data-key="horimeterStart"></td><td><input type="number" step="0.1" value="${h(u.horimeterEnd||'')}" data-rdo-equip="${h(e.id)}" data-key="horimeterEnd"></td><td><input value="${h(u.reason||'')}" placeholder="Motivo se parado" data-rdo-equip="${h(e.id)}" data-key="reason"></td></tr>`}).join('');html+=`<div class="table-wrap"><table class="rdo-detail-table"><thead><tr><th>Equipamento / veículo</th><th>Operador</th><th>Status</th><th>H. op.</th><th>H. parada</th><th>Horím. ini.</th><th>Horím. fim</th><th>Justificativa</th></tr></thead><tbody>${rows}</tbody></table></div>`}if(paradosEquip.length>0){html+=`<div class="rdo-parados-section"><div class="rdo-section-title">⏸ Parados (não selecionados)</div><div class="list">${paradosEquip.map(e=>`<div class="rdo-parados-item"><div><b>${h(e.prefix)}</b><div class="muted">${h(e.type)}</div></div><div style="flex:1"><select data-rdo-parado="equip:${h(e.id)}" style="width:100%"><option value="">— Motivo —</option>${paradosReasonOptions.map(opt=>`<option value="${h(opt)}" ${r.paradosReasons?.['equip:'+e.id]===opt?'selected':''}>${h(opt)}</option>`).join('')}</select></div></div>`).join('')}</div></div>`}return html||`<div class="rdo-empty">Clique em + para selecionar equipamentos.</div>`}
function rdoLightVehiclesEditor(r){const selected=state.rdoSelectedVehicles||new Set();const allVehicles=D.lightVehicles||[];const selectedVehicles=allVehicles.filter(v=>selected.has(v.id));const paradosVehicles=allVehicles.filter(v=>!selected.has(v.id));let html='';if(selectedVehicles.length>0){const rows=selectedVehicles.map(v=>{return `<tr><td><b>${h(v.prefix)}</b><div class="muted small">${h(v.brand)} ${h(v.model)} · ${h(v.plate)}</div></td><td>${h(v.year)}</td><td><select data-rdo-vehicle="${h(v.id)}" data-key="operator">${rdoPersonOptions('')}</select></td><td><input type="number" step="0.1" min="0" value="0" data-rdo-vehicle="${h(v.id)}" data-key="distance" placeholder="km"></td><td><input value="" data-rdo-vehicle="${h(v.id)}" data-key="reason"></td></tr>`}).join('');html+=`<div class="table-wrap"><table class="rdo-detail-table"><thead><tr><th>Veículo leve</th><th>Ano</th><th>Motorista</th><th>Distância</th><th>Observação</th></tr></thead><tbody>${rows}</tbody></table></div>`}if(paradosVehicles.length>0){html+=`<div class="rdo-parados-section"><div class="rdo-section-title">⏸ Parados (não selecionados)</div><div class="list">${paradosVehicles.map(v=>`<div class="rdo-parados-item"><div><b>${h(v.prefix)}</b><div class="muted">${h(v.brand)} ${h(v.model)} · ${h(v.plate)}</div></div><div style="flex:1"><select data-rdo-parado="vehicle:${h(v.id)}" style="width:100%"><option value="">— Motivo —</option>${paradosReasonOptions.map(opt=>`<option value="${h(opt)}" ${r.paradosReasons?.['vehicle:'+v.id]===opt?'selected':''}>${h(opt)}</option>`).join('')}</select></div></div>`).join('')}</div></div>`}if(!selectedVehicles.length&&!paradosVehicles.length)html+=`<div class="rdo-empty">Clique em + para selecionar veículos leves.</div>`;return html}
function rdoActivitiesEditor(r){const selected=state.rdoSelectedActivities||new Set();const allActivities=D.activitiesCatalog.filter(a=>a.active);const selectedActivities=allActivities.filter(a=>selected.has(a.id));const paradosActivities=allActivities.filter(a=>!selected.has(a.id));let html='';if(selectedActivities.length>0){const rows=selectedActivities.map(a=>{let x=r.activities.find(v=>v.catalogId===a.id);if(!x)x={id:'',catalogId:a.id,description:a.description,location:'',qty:0,unit:a.unit,status:'andamento',wbs:''};return `<tr><td><label class="check-label"><span style="cursor:pointer"><b>${h(a.description)}</b></span></label></td><td><select data-rdo-act="${h(a.id)}" data-key="wbs">${rdoWbsOptions(x.wbs)}</select></td><td><input value="${h(x.location||'')}" data-rdo-act="${h(a.id)}" data-key="location"></td><td><input type="number" step="0.001" min="0" value="${h(x.qty||0)}" data-rdo-act="${h(a.id)}" data-key="qty"></td><td>${h(a.unit||x.unit||'—')}</td><td><select data-rdo-act="${h(a.id)}" data-key="status">${option('andamento','Em andamento',x.status==='andamento')}${option('concluida','Concluída',x.status==='concluida')}${option('paralisada','Paralisada',x.status==='paralisada')}</select></td></tr>`}).join('');html+=`<div class="table-wrap"><table class="rdo-detail-table"><thead><tr><th>Atividade</th><th>EAP</th><th>Local</th><th>Qtd.</th><th>Un.</th><th>Status</th></tr></thead><tbody>${rows}</tbody></table></div>`}if(paradosActivities.length>0){html+=`<div class="rdo-parados-section"><div class="rdo-section-title">⏸ Parados (não selecionadas)</div><div class="list">${paradosActivities.map(a=>`<div class="rdo-parados-item"><div><b>${h(a.description)}</b></div><div style="flex:1"><select data-rdo-parado="activity:${h(a.id)}" style="width:100%"><option value="">— Motivo —</option>${paradosReasonOptions.map(opt=>`<option value="${h(opt)}" ${r.paradosReasons?.['activity:'+a.id]===opt?'selected':''}>${h(opt)}</option>`).join('')}</select></div></div>`).join('')}</div></div>`}const extras=r.activities.filter(x=>!x.catalogId).map(x=>`<div class="rdo-item"><div><b>${h(x.description)}</b><div class="rdo-item-meta">${h(x.location||'Sem local')} · ${h(x.qty||0)} ${h(x.unit||'')} · ${h(x.status||'andamento')}</div></div>${iconBtn('×',`rdo-remove-extra:${x.id}`,'Remover')}</div>`).join('');return html+(extras||''?(extras?`<div style="margin-top:12px"><div class="rdo-section-title">🔧 Atividades avulsas</div><div class="list">${extras}</div>${btn('+ Atividade avulsa','rdoAddActivity')}</div>`:btn('+ Atividade avulsa','rdoAddActivity')):`<div style="margin-top:12px">${btn('+ Atividade avulsa','rdoAddActivity')}</div>`)}
function rdoEventsEditor(r,kind){const arr=kind==='safety'?r.safetyEvents:r.environmentEvents;return `<div class="list">${arr.map(ev=>`<div class="rdo-item"><div><b>${h(ev.type)}</b> ${statusPill(ev.severity)}<div class="rdo-item-meta">${h(ev.description||'')}</div>${ev.action?`<div class="rdo-item-meta"><b>Ação:</b> ${h(ev.action)}</div>`:''}</div>${iconBtn('×',`rdo-remove-event:${kind}:${ev.id}`,'Remover')}</div>`).join('')||`<div class="rdo-empty">Nenhum evento registrado.</div>`}</div>${btn('+ Registrar evento',kind==='safety'?'rdoAddSafety':'rdoAddEnvironment')}`}
function rdoPhotosEditor(r){return `<div class="rdo-photo-grid">${r.photos.map((f,i)=>`<div class="rdo-photo"><img src="${h(f.dataUrl)}" alt="Foto ${i+1}"><input placeholder="Legenda" value="${h(f.caption||'')}" data-rdo-photo="${i}" data-key="caption"><select data-rdo-photo="${i}" data-key="activityId"><option value="">Geral</option>${r.activities.map(a=>option(a.id,a.description.slice(0,50),a.id===f.activityId)).join('')}</select>${iconBtn('Remover',`rdo-remove-photo:${i}`,'Remover foto')}</div>`).join('')}</div><div class="info-box">${r.photos.length}/20 fotos · no modo offline as imagens são compactadas e ficam apenas neste navegador.</div>${r.photos.length<20?`${btn('📷 Adicionar foto','rdoAddPhoto')}<input type="file" id="rdoPhotoInput" accept="image/*" style="display:none">`:''}`}
function rdoEditor(r){const editable=can('rdo','edit')||can('rdo','create');return `<div class="rdo-container"><div class="rdo-section"><div class="rdo-section-title">📅 Data e local</div><div class="rdo-field"><label>Data</label><input type="date" value="${h(r.date)}" data-rdo-field="date"></div><div class="rdo-field"><label>Local da obra</label><input value="${h(r.location.local)}" data-rdo-field="location.local" placeholder="Ex.: Bloco A — 2º pavimento"></div><div class="rdo-field"><label>Descrição</label><textarea data-rdo-field="location.description">${h(r.location.description)}</textarea></div><div class="actions gap-top">${btn('Copiar do último diário','rdoCopyPrevious')}</div></div><div class="rdo-section"><div class="rdo-section-title">🌤 Tempo</div><div><strong>Manhã</strong><div class="rdo-clima-chips">${['sol','nublado','chuva'].map(t=>`<button class="rdo-chip ${r.climate?.manha===t?'active':''}" onclick="setRdoClimate('manha','${t}');renderAll()">${{sol:'☀️ Sol',nublado:'⛅ Nublado',chuva:'🌧️ Chuva'}[t]}</button>`).join('')}</div></div><div style="margin-top:12px"><strong>Tarde</strong><div class="rdo-clima-chips">${['sol','nublado','chuva'].map(t=>`<button class="rdo-chip ${r.climate?.tarde===t?'active':''}" onclick="setRdoClimate('tarde','${t}');renderAll()">${{sol:'☀️ Sol',nublado:'⛅ Nublado',chuva:'🌧️ Chuva'}[t]}</button>`).join('')}</div></div></div><div class="rdo-section"><div class="rdo-section-title">⏰ Jornada</div><div style="display:grid;grid-template-columns:repeat(4,1fr);gap:8px"><div class="rdo-field"><label>Início</label><input type="time" value="${h(r.journey.start)}" data-rdo-field="journey.start"></div><div class="rdo-field"><label>Alm. ini.</label><input type="time" value="${h(r.journey.lunchStart)}" data-rdo-field="journey.lunchStart"></div><div class="rdo-field"><label>Alm. fim</label><input type="time" value="${h(r.journey.lunchEnd)}" data-rdo-field="journey.lunchEnd"></div><div class="rdo-field"><label>Fim</label><input type="time" value="${h(r.journey.end)}" data-rdo-field="journey.end"></div></div></div><div class="rdo-section"><div class="rdo-section-title">📋 DSS</div><div class="rdo-field"><label>Ministrado por</label><select data-rdo-field="dssDetail.instructor">${rdoPersonOptions(r.dssDetail.instructor)}</select></div><div class="rdo-field"><label>Tema</label><textarea data-rdo-field="dssDetail.theme">${h(r.dssDetail.theme)}</textarea></div></div><div class="rdo-section"><div class="rdo-section-title">👷 Efetivo ${iconBtn('+','modalSelectPeople','Selecionar')}</div><div class="rdo-stats-row"><div class="rdo-stat"><div class="rdo-stat-num">${rdoAttendanceCount(r)}</div><div class="rdo-stat-label">Presentes</div></div><div class="rdo-stat"><div class="rdo-stat-num">${D.people.filter(p=>p.status==='ativo').length}</div><div class="rdo-stat-label">Cadastro</div></div><div class="rdo-stat"><div class="rdo-stat-num">${sum(r.attendance.filter(a=>a.status==='presente'),a=>num(a.normal)+num(a.extra)).toLocaleString('pt-BR')}</div><div class="rdo-stat-label">HH</div></div></div>${rdoAttendanceEditor(r)}</div><div class="rdo-section"><div class="rdo-section-title">🚜 Equipamentos ${iconBtn('+','modalSelectEquipment','Sel')} ${iconBtn('+','modalSelectLightVehicles','V.L')}</div>${rdoEquipmentEditor(r)}${rdoLightVehiclesEditor(r)}</div><div class="rdo-section"><div class="rdo-section-title">🛠 Atividades ${iconBtn('+','modalSelectActivities','Sel')}</div>${rdoActivitiesEditor(r)}</div><div class="rdo-section"><div class="rdo-section-title">📝 Observações</div><textarea data-rdo-field="notes" style="width:100%;min-height:100px">${h(r.notes)}</textarea></div><div style="display:grid;grid-template-columns:1fr 1fr;gap:12px"><div class="rdo-section"><div class="rdo-section-title">🦺 Segurança</div>${rdoEventsEditor(r,'safety')}</div><div class="rdo-section"><div class="rdo-section-title">🌱 Ambiente</div>${rdoEventsEditor(r,'environment')}</div></div><div class="rdo-section"><div class="rdo-section-title">📷 Fotos</div>${rdoPhotosEditor(r)}</div><div class="rdo-section"><div class="rdo-section-title">✍️ Responsável</div><div class="rdo-field"><select data-rdo-field="responsible">${rdoPersonOptions(r.responsible)}</select></div><div class="actions gap-top">${r.status!=='emitido'?btn('Emitir RDO','rdoFinalize',true):statusPill('emitido')}${can('rdo','delete')?btn('Excluir','rdoDelete'):''}</div></div></div>`}
function setRdoClimate(periodo,tipo){const r=rdoSelected();if(!r)return;if(!r.climate)r.climate={};r.climate[periodo]=tipo;persist()}
function rdoText(r){const acts=r.activities.filter(a=>a.status!=='nao_executada').map(a=>`• ${a.description}${a.location?' — '+a.location:''}${num(a.qty)?` — ${a.qty} ${a.unit||''}`:''} [${a.status}]`).join('\n')||'• Sem atividades';const ev=[...r.safetyEvents,...r.environmentEvents];return `RDO Nº ${String(r.number).padStart(3,'0')} — ${dateBR(r.date)}\nObra: ${state.work.name}\nLocal: ${r.location.local||'—'}\nClima: manhã ${rdoWeatherLabel(r,'manha')} / tarde ${rdoWeatherLabel(r,'tarde')} · chuva ${rdoRain(r).toFixed(1)} mm\nEfetivo: ${rdoAttendanceCount(r)} presentes\nEquipamentos: ${rdoEquipCount(r)} utilizados\nDSS: ${r.dssDetail.theme||'—'}\n\nATIVIDADES\n${acts}\n\nOBSERVAÇÕES\n${r.notes||'—'}${ev.length?`\n\nEVENTOS SSMA: ${ev.length}`:''}`}
function rdoReport(r){const climate=['madrugada','manha','tarde','noite'].map(p=>{const x=r.climate[p];return `<tr><td>${p[0].toUpperCase()+p.slice(1)}</td><td>${h(rdoWeatherLabel(r,p))}</td><td>${h(x.operacao)}</td><td>${num(x.chuvaMm).toLocaleString('pt-BR')}</td></tr>`}).join('');const acts=r.activities.filter(a=>a.status!=='nao_executada').map((a,i)=>`<tr><td>${i+1}</td><td>${h(a.description)}</td><td>${h(a.location||'—')}</td><td>${h(a.qty||'—')} ${h(a.unit||'')}</td><td>${h(a.status)}</td></tr>`).join('');const att=r.attendance.filter(a=>a.status==='presente').map(a=>{const p=rdoPerson(a.person);return `<tr><td>${h(p?.name||a.person)}</td><td>${h(p?.function||'')}</td><td>${h(a.normal)}</td><td>${h(a.extra)}</td></tr>`}).join('');const eq=r.equipmentUse.filter(x=>x.active).map(x=>{const e=rdoEquipment(x.equipment);return `<tr><td>${h(e?.prefix||'')}</td><td>${h(e?.type||'')}</td><td>${h(rdoPerson(x.operator)?.name||'—')}</td><td>${h(x.status)}</td><td>${h(x.hoursOperating)}</td><td>${h(x.hoursStopped)}</td></tr>`}).join('');const events=[...r.safetyEvents.map(x=>({...x,domain:'Segurança'})),...r.environmentEvents.map(x=>({...x,domain:'Meio Ambiente'}))];return `<div class="rdo-report rdo-print-area" id="rdoReportPrint"><div class="rdo-report-head"><div><h1>RELATÓRIO DIÁRIO DE OBRA</h1><b>${h(state.work.name)}</b><div>${h(state.work.code||'')} · ${dateBR(r.date)}</div></div><div class="rdo-number">RDO<br><b>${String(r.number).padStart(3,'0')}</b></div></div><div class="kpi-strip"><span>Efetivo <b>${rdoAttendanceCount(r)}</b></span><span>Equipamentos <b>${rdoEquipCount(r)}</b></span><span>Atividades <b>${r.activities.filter(a=>a.status!=='nao_executada').length}</b></span><span>Chuva <b>${rdoRain(r).toFixed(1)} mm</b></span><span>Fotos <b>${r.photos.length}</b></span></div><h2>Identificação</h2><p><b>Local:</b> ${h(r.location.local||'—')}<br>${h(r.location.description||'')}</p><h2>Condições climáticas</h2><table><thead><tr><th>Período</th><th>Tempo</th><th>Operação</th><th>mm</th></tr></thead><tbody>${climate}</tbody></table><h2>Jornada e DSS</h2><p><b>Jornada:</b> ${h(r.journey.start)}–${h(r.journey.lunchStart)} / ${h(r.journey.lunchEnd)}–${h(r.journey.end)}<br><b>DSS:</b> ${h(r.dssDetail.time)} · ${h(rdoPerson(r.dssDetail.instructor)?.name||'—')} · ${h(r.dssDetail.theme||'—')}</p><h2>Atividades do dia</h2><table><thead><tr><th>#</th><th>Descrição</th><th>Local</th><th>Quantidade</th><th>Status</th></tr></thead><tbody>${acts||'<tr><td colspan="5">Sem atividades</td></tr>'}</tbody></table><h2>Efetivo</h2><table><thead><tr><th>Nome</th><th>Função</th><th>HN</th><th>HE</th></tr></thead><tbody>${att||'<tr><td colspan="4">Sem presença detalhada</td></tr>'}</tbody></table><h2>Equipamentos</h2><table><thead><tr><th>Prefixo</th><th>Tipo</th><th>Operador</th><th>Status</th><th>H. op.</th><th>H. parada</th></tr></thead><tbody>${eq||'<tr><td colspan="6">Sem equipamentos</td></tr>'}</tbody></table>${r.pausedActivities.length?`<h2>Atividades paralisadas</h2><ul>${r.pausedActivities.map(x=>`<li><b>${h(x.description)}</b> — ${h(x.reason||'Sem justificativa')}</li>`).join('')}</ul>`:''}${events.length?`<h2>Eventos SSMA</h2><ul>${events.map(x=>`<li><b>${h(x.domain)} · ${h(x.type)} (${h(x.severity)})</b> — ${h(x.description)}${x.action?' · Ação: '+h(x.action):''}</li>`).join('')}</ul>`:''}<h2>Observações</h2><p>${h(r.notes||'—')}</p>${r.photos.length?`<h2>Registro fotográfico</h2><div class="rdo-report-photos">${r.photos.map(f=>`<figure><img src="${h(f.dataUrl)}"><figcaption>${h(f.caption||'')}</figcaption></figure>`).join('')}</div>`:''}<div class="rdo-sign-grid"><div>${r.signatures.apontador?`<img src="${h(r.signatures.apontador)}">`:''}<div class="sig-line"></div><b>${h(rdoPerson(r.responsible)?.name||'Apontador')}</b><br>Apontador</div><div>${r.signatures.fiscal?`<img src="${h(r.signatures.fiscal)}">`:''}<div class="sig-line"></div><b>Fiscalização / Cliente</b></div></div></div>`}
function rdoSummary(){const base=rdoSelected()?.date||todayISO();const d=new Date(base+'T12:00:00');let start,end;if(state.rdoSummaryMode==='ano'){start=`${d.getFullYear()}-01-01`;end=`${d.getFullYear()}-12-31`}else if(state.rdoSummaryMode==='semana'){const day=(d.getDay()+6)%7;const a=new Date(d);a.setDate(a.getDate()-day);const b=new Date(a);b.setDate(b.getDate()+6);start=a.toISOString().slice(0,10);end=b.toISOString().slice(0,10)}else{start=`${base.slice(0,7)}-01`;const b=new Date(d.getFullYear(),d.getMonth()+1,0);end=b.toISOString().slice(0,10)}const rows=D.rdos.map(rdoNormalize).filter(r=>r.date>=start&&r.date<=end);const qty={};rows.forEach(r=>r.activities.filter(a=>a.status!=='nao_executada').forEach(a=>{const k=a.description+'|'+(a.unit||'');qty[k]=(qty[k]||0)+num(a.qty)}));return `<div class="rdo-summary-controls">${tabs([{id:'semana',label:'Semana'},{id:'mes',label:'Mês'},{id:'ano',label:'Ano'}],state.rdoSummaryMode,'rdoSummary')}</div><div class="grid-4"><div class="card metric"><span>Dias registrados</span><b>${rows.length}</b></div><div class="card metric"><span>Efetivo médio</span><b>${rows.length?avg(rows.map(rdoAttendanceCount)).toFixed(1):'0'}</b></div><div class="card metric"><span>Chuva acumulada</span><b>${sum(rows,rdoRain).toFixed(1)} mm</b></div><div class="card metric"><span>Fotos</span><b>${sum(rows,r=>r.photos.length)}</b></div></div><div class="grid-2 gap-top"><div class="card section"><h2>🛠 Serviços executados</h2>${Object.keys(qty).length?`<table><thead><tr><th>Serviço</th><th>Total</th></tr></thead><tbody>${Object.entries(qty).map(([k,v])=>`<tr><td>${h(k.split('|')[0])}</td><td>${v.toLocaleString('pt-BR')} ${h(k.split('|')[1])}</td></tr>`).join('')}</tbody></table>`:empty('Sem quantidades no período.')}</div><div class="card section"><h2>👷 Efetivo por dia</h2>${rows.length?`<table><thead><tr><th>Data</th><th>Presentes</th><th>H-H</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${dateBR(r.date)}</td><td>${rdoAttendanceCount(r)}</td><td>${sum(r.attendance.filter(a=>a.status==='presente'),a=>num(a.normal)+num(a.extra)).toLocaleString('pt-BR')}</td></tr>`).join('')}</tbody></table>`:empty()}</div></div>`}
function rdoCalendar(){const [y,m]=state.rdoCalendarAnchor.split('-').map(Number);const first=new Date(y,m-1,1),last=new Date(y,m,0);const cells=[];for(let i=0;i<first.getDay();i++)cells.push('<div class="rdo-cal-cell blank"></div>');for(let day=1;day<=last.getDate();day++){const date=`${y}-${String(m).padStart(2,'0')}-${String(day).padStart(2,'0')}`;const r=D.rdos.find(x=>x.date===date);cells.push(`<button class="rdo-cal-cell ${r?'has-rdo':''}" data-rdo-date="${h(date)}" ${r?`data-rdo="${h(r.id)}"`:''}><b>${day}</b>${r?`<span>RDO ${String(r.number).padStart(3,'0')}</span>`:''}</button>`)}return `<div class="card section"><div class="rdo-cal-head">${btn('‹','rdoCalPrev')}<h2>${first.toLocaleDateString('pt-BR',{month:'long',year:'numeric'})}</h2>${btn('›','rdoCalNext')}</div><div class="rdo-cal-week">${['Dom','Seg','Ter','Qua','Qui','Sex','Sáb'].map(x=>`<b>${x}</b>`).join('')}</div><div class="rdo-calendar-grid">${cells.join('')}</div></div>`}
function rdoCadastro(){return `<div class="grid-3"><div class="card section"><h2>👷 Equipe</h2><p>${D.people.filter(p=>p.status==='ativo').length} colaboradores ativos vinculados ao Cadastro Premium.</p>${btn('Abrir Efetivo','rdoGoWorkforce',true)}</div><div class="card section"><h2>🚜 Equipamentos</h2><p>${D.equipment.length} equipamentos/veículos disponíveis para apontamento.</p>${btn('Abrir Equipamentos','rdoGoEquipment',true)}</div><div class="card section"><h2>🛠 Atividades</h2><p>${D.activitiesCatalog.filter(a=>a.active).length} atividades do catálogo corporativo disponíveis.</p>${btn('Abrir Cadastro','rdoGoCatalog',true)}</div></div><div class="card section gap-top"><h2>Regra recuperada do RDO anterior</h2><p>O RDO usa os cadastros corporativos/da obra e não mantém listas paralelas. O apontamento diário registra presença, horas, atividade, quantidade, equipamento, operador, clima, SSMA, fotos e assinaturas preservando o histórico.</p></div>`}
function rdoPage(){const selected=rdoSelected();const actions=can('rdo','create')?btn('Novo RDO','newRdo',true):'';const top=pageHead('RDO','Diário completo: campo, clima, jornada, DSS, efetivo, equipamentos, atividades, SSMA, fotos, assinaturas, resumo e calendário.',actions);const nav=tabs([{id:'diario',label:'📝 Diário'},{id:'gerar',label:'📤 Gerar'},{id:'resumo',label:'📊 Resumo'},{id:'calendario',label:'📅 Calendário'},{id:'cadastro',label:'⚙ Cadastro'}],state.rdoTab,'rdo');let body='';if(state.rdoTab==='diario')body=selected?`${rdoEditor(selected)}<div class="card section gap-top"><h2>Histórico</h2>${rdoTable(D.rdos)}</div>`:`<div class="card section">${rdoTable(D.rdos)}</div>`;if(state.rdoTab==='gerar')body=selected?`<div class="actions gap-bottom">${btn('Imprimir / Salvar PDF','printRdo',true)}${btn('Copiar texto','rdoCopyText')}${btn(selected.signatures.apontador?'Refazer assinatura apontador':'Assinar apontador','rdoSignApontador')}${btn(selected.signatures.fiscal?'Refazer assinatura fiscalização':'Assinar fiscalização','rdoSignFiscal')}</div>${rdoReport(selected)}`:empty('Selecione um RDO.');if(state.rdoTab==='resumo')body=rdoSummary();if(state.rdoTab==='calendario')body=rdoCalendar();if(state.rdoTab==='cadastro')body=rdoCadastro();return `<div class="rdo-page">${top}${nav}<div class="gap-top">${body}</div></div>`}
function reportsPage(f){const actions=can('relatorios','generate')?`${btn('Imprimir executivo','printExecutive',true)}${btn('Exportar financeiro CSV','csvFinancial')}${btn('Exportar RDO CSV','csvRdo')}`:'';return pageHead('Relatórios','Visões executivas, financeiras e operacionais para emissão.',actions)+`<div id="reportArea"><div class="grid-3"><div class="card section"><h3>Resumo executivo</h3>${financialList([['Orçamento atual',f.current],['Comprometido',f.commitments],['Realizado',f.realized],['Forecast',f.forecast]])}</div><div class="card section"><h3>Produção</h3>${financialList([['Avanço físico',physicalProgress().physical],['PPC semanal',ppc()],['RDOs emitidos',D.rdos.length],['Restrições abertas',D.restrictions.filter(r=>r.status!=='concluida').length]])}</div><div class="card section"><h3>Gestão</h3>${financialList([['Contratos ativos',D.contracts.filter(c=>c.status==='ativo').length],['Tarefas abertas',D.tasks.filter(t=>t.status!=='concluida').length],['Alertas não lidos',D.alerts.filter(a=>!a.read).length],['Documentos',D.documents.length]])}</div></div><div class="card section gap-top"><h2>Resumo de EAP</h2><table><thead><tr><th>EAP</th><th>Planejado</th><th>Real</th><th>Desvio</th></tr></thead><tbody>${D.wbs.filter(w=>!w.parent).map(w=>`<tr><td>${h(w.code+' '+w.name)}</td><td>${pct(w.planned)}</td><td>${pct(w.progress)}</td><td class="${w.progress<w.planned?'metric-negative':'metric-positive'}">${(w.progress-w.planned).toFixed(1)} p.p.</td></tr>`).join('')}</tbody></table></div></div>`}
function muralPage(){const actions=btn('Novo aviso','newMuralEntry',true);return pageHead('Mural de avisos','Comunicados, anúncios e prioridades da obra.',actions)+`<div class="card section"><div class="notes-list">${D.mural.slice().reverse().map(m=>`<div class="note-item"><div class="note-head"><b>${h(m.autor)}</b> · ${new Date(m.criado_em).toLocaleString('pt-BR')}${can('reunioes','edit')?`<button onclick="event.stopPropagation();deleteMuralEntry('${m.id}'); return false;" style="float:right;padding:2px 4px;font-size:11px;">×</button>`:''}</div><div class="note-text">${h(m.texto)}</div></div>`).join('')||empty('Sem avisos no mural.')}</div></div>`}

function eapPage(){
  const actions=can('orcamento','edit')?btn('Novo item EAP','newEap',true):'';
  const rows=[...D.wbs].sort((a,b)=>a.code.localeCompare(b.code,'pt-BR',{numeric:true}));
  return pageHead('EAP da Obra','Estrutura hierárquica que integra planejamento, orçamento, contratos, custos e documentos.',actions)+`<div class="card section"><table><thead><tr><th>Código</th><th>Nome</th><th>Pai</th><th>Planejado</th><th>Real</th><th>Nível</th></tr></thead><tbody>${rows.map(w=>`<tr><td><b>${h(w.code)}</b></td><td>${h(w.name)}</td><td>${h(w.parent?wbsName(w.parent):'Raiz')}</td><td>${pct(w.planned)}</td><td>${pct(w.progress)}</td><td>${w.parent?'Pacote':'Grupo'}</td></tr>`).join('')}</tbody></table><div class="info-box">Itens já vinculados a orçamento, contratos ou planejamento não devem ser apagados; devem ser inativados no backend produtivo.</div></div>`;
}
function procurementCommitted(){return sum((D.purchaseOrders||[]).filter(poApproved),p=>p.amount)}
function suppliesPage(){
  const actions=can('suprimentos','create')?`${btn('Nova solicitação','newPurchaseRequest',true)}${btn('Nova cotação','newPurchaseQuote')}`:'';
  const tb=tabs([{id:'requisicoes',label:'Solicitações'},{id:'cotacoes',label:'Cotações'},{id:'pedidos',label:'Pedidos de Compra'},{id:'recebimentos',label:'Recebimentos'}],state.procurementTab,'procurement');
  let body='';
  if(state.procurementTab==='requisicoes')body=`<div class="card section"><table><thead><tr><th>Número</th><th>EAP</th><th>CBS</th><th>Descrição</th><th>Estimado</th><th>Responsável</th><th>Status</th></tr></thead><tbody>${(D.purchaseRequests||[]).map(r=>`<tr><td><b>${h(r.number)}</b></td><td>${h(wbsName(r.wbs))}</td><td>${h(cbsName(r.cbs))}</td><td>${h(r.description)}</td><td>${money(r.estimated)}</td><td>${h(r.owner)}</td><td>${statusPill(r.status)}</td></tr>`).join('')}</tbody></table></div>`;
  if(state.procurementTab==='cotacoes')body=`<div class="card section"><table><thead><tr><th>Solicitação</th><th>Fornecedor</th><th>Valor</th><th>Prazo</th><th>Pagamento</th><th>Selecionada</th><th></th></tr></thead><tbody>${(D.purchaseQuotes||[]).map(q=>`<tr><td>${h(q.request)}</td><td>${h(q.supplier)}</td><td>${money(q.amount)}</td><td>${h(q.leadDays)} dias</td><td>${h(q.payment)}</td><td>${statusPill(q.selected?'Sim':'Não')}</td><td>${!q.selected&&can('suprimentos','edit')?iconBtn('Selecionar',`select-quote:${q.id}`):''}${q.selected&&can('suprimentos','create')&&!D.purchaseOrders.some(p=>p.request===q.request)?iconBtn('Gerar PC',`quote-order:${q.id}`):''}</td></tr>`).join('')||'<tr><td colspan="7">Sem cotações.</td></tr>'}</tbody></table></div>`;
  if(state.procurementTab==='pedidos')body=`<div class="kpi-grid"><div class="card kpi"><div class="kpi-label">PEDIDOS</div><div class="kpi-value">${D.purchaseOrders.length}</div></div><div class="card kpi"><div class="kpi-label">COMPROMETIDO</div><div class="kpi-value">${moneyM(procurementCommitted())}</div></div><div class="card kpi"><div class="kpi-label">EM APROVAÇÃO</div><div class="kpi-value">${D.purchaseOrders.filter(p=>p.status==='em_aprovacao').length}</div></div><div class="card kpi"><div class="kpi-label">RECEBIMENTOS</div><div class="kpi-value">${D.receipts.length}</div></div></div><div class="card section"><table><thead><tr><th>Pedido</th><th>Fornecedor</th><th>EAP</th><th>CBS</th><th>Descrição</th><th>Valor</th><th>Status</th><th></th></tr></thead><tbody>${D.purchaseOrders.map(p=>`<tr><td><b>${h(p.number)}</b></td><td>${h(p.supplier)}</td><td>${h(wbsName(p.wbs))}</td><td>${h(cbsName(p.cbs))}</td><td>${h(p.description)}</td><td>${money(p.amount)}</td><td>${statusPill(p.status)}</td><td>${p.status==='em_aprovacao'&&can('suprimentos','approve')?iconBtn('Aprovar',`approve-po:${p.id}`):''}${poApproved(p)&&poBalance(p)>0&&can('suprimentos','edit')?iconBtn('Receber',`receive-po:${p.id}`):''}</td></tr>`).join('')}</tbody></table><div class="info-box">Pedido aprovado passa a consumir orçamento automaticamente, mesmo antes da NF.</div></div>`;
  if(state.procurementTab==='recebimentos')body=`<div class="card section"><table><thead><tr><th>Data</th><th>Pedido</th><th>Descrição</th><th>Valor recebido</th><th>Recebedor</th></tr></thead><tbody>${D.receipts.map(r=>`<tr><td>${dateBR(r.date)}</td><td>${h(r.order)}</td><td>${h(r.description)}</td><td>${money(r.amount)}</td><td>${h(r.owner)}</td></tr>`).join('')||'<tr><td colspan="5">Sem recebimentos.</td></tr>'}</tbody></table></div>`;
  return pageHead('Suprimentos','Solicitação → cotação → pedido → recebimento → NF, com comprometimento de verba.',actions)+tb+body;
}
function brainInsights(){
  const f=financial(),out=[];
  const worst=[...D.planning].sort((a,b)=>(a.actual-a.planned)-(b.actual-b.planned))[0];
  if(worst&&worst.actual<worst.planned)out.push({level:'critica',title:'Maior desvio de planejamento',text:`${worst.activity}: ${worst.actual}% realizado x ${worst.planned}% planejado (${(worst.actual-worst.planned).toFixed(1)} p.p.).`,action:'Priorizar remoção de restrições e plano de recuperação.'});
  if(f.projected<0)out.push({level:'critica',title:'Forecast acima do orçamento',text:`Projeção excede o orçamento atual em ${money(Math.abs(f.projected))}.`,action:'Revisar ETC, compromissos e escopo.'});
  else out.push({level:'ok',title:'Forecast dentro do orçamento',text:`Saldo projetado de ${moneyM(f.projected)}.`,action:'Manter revisão semanal do ETC.'});
  D.contracts.filter(contractApproved).forEach(c=>{const v=contractValue(c),saldo=v-measuredContract(c.id);if(v&&saldo/v<.2)out.push({level:'atencao',title:`Saldo contratual baixo — ${c.number}`,text:`Saldo ${moneyM(saldo)} (${pct(saldo/v*100)}).`,action:'Avaliar aditivo, saldo físico e escopo remanescente.'})});
  const overdue=D.restrictions.filter(r=>r.status!=='concluida'&&r.due<todayISO());if(overdue.length)out.push({level:'critica',title:'Restrições vencidas',text:`${overdue.length} restrição(ões) com prazo vencido.`,action:'Escalonar responsáveis e registrar nova data compromisso.'});
  const pendingPO=D.purchaseOrders.filter(p=>p.status==='em_aprovacao');if(pendingPO.length)out.push({level:'atencao',title:'Pedidos aguardando aprovação',text:`${pendingPO.length} pedido(s) somando ${moneyM(sum(pendingPO,p=>p.amount))}.`,action:'Aprovar ou devolver antes de comprometer a programação.'});
  const unread=D.alerts.filter(a=>!a.read);if(unread.length)out.push({level:'atencao',title:'Alertas não tratados',text:`${unread.length} alerta(s) ainda não lidos.`,action:'Revisar o painel de alertas.'});
  return out;
}
function brainPage(){const ins=brainInsights();return pageHead('Brain','Análise local do estado da obra, sem API externa e sem custo adicional.',btn('Atualizar análise','refreshBrain',true))+`<div class="brain-banner"><b>Brain Local</b><span>Esta edição usa regras determinísticas sobre os dados da obra. Não envia dados para serviços externos.</span></div><div class="grid-3">${ins.map(i=>`<div class="card section"><div class="card-title-line"><h3>${h(i.title)}</h3>${statusPill(i.level)}</div><p>${h(i.text)}</p><div class="info-box"><b>Ação sugerida:</b> ${h(i.action)}</div></div>`).join('')}</div>`}
function auditPage(){const list=D.auditTrail||[];return pageHead('Auditoria','Trilha local das principais operações desta demonstração.')+`<div class="card section"><table><thead><tr><th>Data/hora</th><th>Módulo</th><th>Ação</th><th>Referência</th><th>Usuário</th><th>Detalhe</th></tr></thead><tbody>${list.map(a=>`<tr><td>${h(new Date(a.date).toLocaleString('pt-BR'))}</td><td>${h(a.module)}</td><td><b>${h(a.action)}</b></td><td>${h(a.reference)}</td><td>${h(a.user)}</td><td>${h(a.detail)}</td></tr>`).join('')||'<tr><td colspan="6">Sem eventos.</td></tr>'}</tbody></table></div>`}
function modalEap(){openModal('Novo item EAP',`<div class="form-grid">${field('Código',input('eapCode','07'))}${field('Nome',input('eapName','Novo pacote'))}${field('Pai',select('eapParent',[{value:'',label:'Raiz'},...D.wbs.map(w=>({value:w.id,label:w.code+' '+w.name}))]))}${field('Planejado %',input('eapPlanned','0','number','min="0" max="100"'))}${field('Real %',input('eapActual','0','number','min="0" max="100"'))}</div><div class="modal-actions">${btn('Salvar','saveEap',true)}</div>`)}
function modalPurchaseRequest(){openModal('Nova solicitação de compra',`<div class="form-grid">${field('EAP',`<select id="prWbs">${wbsOptions()}</select>`)}${field('CBS',`<select id="prCbs">${cbsOptions('MAT')}</select>`)}${field('Descrição',input('prDesc','Nova solicitação'),true)}${field('Quantidade',input('prQty','1','number','step="0.001"'))}${field('Unidade',input('prUnit','vb'))}${field('Valor estimado',input('prEstimated','0','number','step="0.01"'))}${field('Responsável',input('prOwner','Suprimentos'))}</div><div class="modal-actions">${btn('Salvar','savePurchaseRequest',true)}</div>`)}
function modalPurchaseQuote(){openModal('Nova cotação',`<div class="form-grid">${field('Solicitação',select('pqRequest',D.purchaseRequests.map(r=>({value:r.id,label:r.number+' · '+r.description}))))}${field('Fornecedor',`<select id="pqSupplier">${supplierOptions()}</select>`)}${field('Valor',input('pqAmount','0','number','step="0.01"'))}${field('Prazo (dias)',input('pqLead','15','number'))}${field('Condição pagamento',input('pqPayment','28 dias'))}</div><div class="modal-actions">${btn('Salvar','savePurchaseQuote',true)}</div>`)}
function modalReceipt(po){const saldo=poBalance(po);openModal('Registrar recebimento',`<div class="form-grid">${field('Pedido',input('recOrder',po.number,'text','readonly'))}${field('Data',input('recDate',todayISO(),'date'))}${field('Descrição',input('recDesc',po.description),true)}${field('Saldo a receber',input('recBalance',String(saldo),'number','readonly'))}${field('Valor recebido',input('recAmount',String(saldo),'number','step="0.01" min="0.01"'))}${field('Recebedor',input('recOwner','Almoxarifado'))}</div><div class="modal-actions">${btn('Salvar','saveReceipt',true)}</div>`) }

function openModal(title,body){$('#modalTitle').textContent=title;$('#modalBody').innerHTML=body;$('#modal').classList.remove('hidden');$('#modal').setAttribute('aria-hidden','false');bindModalActions()}
function closeModal(){$('#modal').classList.add('hidden');$('#modal').setAttribute('aria-hidden','true')}
function workSelector(){openModal('Selecionar Obra',`<div class="work-selector"><div class="list">${D.works.map(w=>`<div class="list-row ${w.id===state.work?.id?'selected':''}"><button onclick="state.work=D.works.find(x=>x.id=='${h(w.id)}');renderAll();closeModal()" style="width:100%;text-align:left;padding:8px;border:none;background:none;cursor:pointer;"><b>${h(w.name)}</b><div class="muted">${h(w.code)} · ${h(w.city)}</div></button></div>`).join('')}</div></div>`)}
function modalSelectPeople(){const selected=state.rdoSelectedPeople||new Set();openModal('Selecionar Efetivo do dia',`<div class="form-grid"><div class="list">${D.people.filter(p=>p.status==='ativo').map(p=>`<div class="list-row"><label style="display:flex;align-items:center;gap:8px;cursor:pointer;width:100%"><input type="checkbox" id="sel-${h(p.id)}" ${selected.has(p.id)?'checked':''} onchange="if(this.checked)state.rdoSelectedPeople.add('${h(p.id)}');else state.rdoSelectedPeople.delete('${h(p.id)}')" style="cursor:pointer"><span><b>${h(p.name)}</b><div class="muted">${h(p.function)}</div></span></label></div>`).join('')}</div></div><div class="modal-actions"><button class="btn primary" onclick="confirmPeopleSelect()">Confirmar</button></div>`)}
function confirmPeopleSelect(){const r=rdoSelected();if(!r)return;state.rdoSelectedPeople=state.rdoSelectedPeople||new Set();$$('#modal input[type="checkbox"]:checked').forEach(el=>{const id=el.id.replace('sel-','');state.rdoSelectedPeople.add(id);if(!r.attendance.find(x=>x.person===id))r.attendance.push({person:id,status:'presente',normal:8,extra:0,obs:''})});$$('#modal input[type="checkbox"]:not(:checked)').forEach(el=>{const id=el.id.replace('sel-','');state.rdoSelectedPeople.delete(id);r.attendance=r.attendance.filter(x=>x.person!==id)});persist();closeModal();renderAll()}
function modalSelectEquipment(){const selected=state.rdoSelectedEquipment||new Set();openModal('Selecionar Equipamentos do dia',`<div class="form-grid"><div class="list">${D.equipment.filter(e=>e.active).map(e=>`<div class="list-row"><label style="display:flex;align-items:center;gap:8px;cursor:pointer;width:100%"><input type="checkbox" id="sel-${h(e.id)}" ${selected.has(e.id)?'checked':''} onchange="if(this.checked)state.rdoSelectedEquipment.add('${h(e.id)}');else state.rdoSelectedEquipment.delete('${h(e.id)}')" style="cursor:pointer"><span><b>${h(e.prefix)}</b><div class="muted">${h(e.type)} · ${h(e.brand)}</div></span></label></div>`).join('')}</div></div><div class="modal-actions"><button class="btn primary" onclick="confirmEquipmentSelect()">Confirmar</button></div>`)}
function confirmEquipmentSelect(){const r=rdoSelected();if(!r)return;state.rdoSelectedEquipment=state.rdoSelectedEquipment||new Set();$$('#modal input[type="checkbox"]:checked').forEach(el=>{const id=el.id.replace('sel-','');state.rdoSelectedEquipment.add(id);if(!r.equipmentUse.find(x=>x.equipment===id))r.equipmentUse.push({equipment:id,active:true,operator:'',status:'operando',hoursOperating:0,hoursStopped:0,reason:'',horimeterStart:'',horimeterEnd:''})});$$('#modal input[type="checkbox"]:not(:checked)').forEach(el=>{const id=el.id.replace('sel-','');state.rdoSelectedEquipment.delete(id);r.equipmentUse=r.equipmentUse.filter(x=>x.equipment!==id)});persist();closeModal();renderAll()}
function modalSelectLightVehicles(){const selected=state.rdoSelectedVehicles||new Set();openModal('Selecionar Veículos Leves do dia',`<div class="form-grid"><div class="list">${D.lightVehicles.filter(v=>v.active).map(v=>`<div class="list-row"><label style="display:flex;align-items:center;gap:8px;cursor:pointer;width:100%"><input type="checkbox" id="sel-${h(v.id)}" ${selected.has(v.id)?'checked':''} onchange="if(this.checked)state.rdoSelectedVehicles.add('${h(v.id)}');else state.rdoSelectedVehicles.delete('${h(v.id)}')" style="cursor:pointer"><span><b>${h(v.prefix)}</b><div class="muted">${h(v.type)} · ${h(v.brand)}</div></span></label></div>`).join('')}</div></div><div class="modal-actions"><button class="btn primary" onclick="confirmVehiclesSelect()">Confirmar</button></div>`)}
function confirmVehiclesSelect(){const r=rdoSelected();if(!r)return;state.rdoSelectedVehicles=state.rdoSelectedVehicles||new Set();if(!r.lightVehiclesUse)r.lightVehiclesUse=[];$$('#modal input[type="checkbox"]:checked').forEach(el=>{const id=el.id.replace('sel-','');state.rdoSelectedVehicles.add(id);if(!r.lightVehiclesUse.find(x=>x.vehicle===id))r.lightVehiclesUse.push({vehicle:id,operator:'',distance:0,reason:''})});$$('#modal input[type="checkbox"]:not(:checked)').forEach(el=>{const id=el.id.replace('sel-','');state.rdoSelectedVehicles.delete(id);r.lightVehiclesUse=r.lightVehiclesUse.filter(x=>x.vehicle!==id)});persist();closeModal();renderAll()}
function modalSelectActivities(){const selected=state.rdoSelectedActivities||new Set();openModal('Selecionar Atividades do dia',`<div class="form-grid"><div class="list">${D.activitiesCatalog.filter(a=>a.active).map(a=>`<div class="list-row"><label style="display:flex;align-items:center;gap:8px;cursor:pointer;width:100%"><input type="checkbox" id="sel-${h(a.id)}" ${selected.has(a.id)?'checked':''} onchange="if(this.checked)state.rdoSelectedActivities.add('${h(a.id)}');else state.rdoSelectedActivities.delete('${h(a.id)}')" style="cursor:pointer"><span><b>${h(a.description)}</b><div class="muted">Un: ${h(a.unit)}</div></span></label></div>`).join('')}</div></div><div class="modal-actions"><button class="btn primary" onclick="confirmActivitiesSelect()">Confirmar</button></div>`)}
function confirmActivitiesSelect(){const r=rdoSelected();if(!r)return;state.rdoSelectedActivities=state.rdoSelectedActivities||new Set();const catalog=D.activitiesCatalog;$$('#modal input[type="checkbox"]:checked').forEach(el=>{const id=el.id.replace('sel-','');state.rdoSelectedActivities.add(id);const cat=catalog.find(a=>a.id===id);if(!r.activities.find(x=>x.catalogId===id))r.activities.push({id:uid('RAT'),catalogId:id,description:cat?.description||'',location:'',qty:0,unit:cat?.unit||'',status:'andamento',wbs:''})});$$('#modal input[type="checkbox"]:not(:checked)').forEach(el=>{const id=el.id.replace('sel-','');state.rdoSelectedActivities.delete(id);r.activities=r.activities.filter(x=>x.catalogId!==id)});persist();closeModal();renderAll()}
function wbsOptions(value=''){return D.wbs.map(w=>({value:w.id,label:`${w.code} ${w.name}`})).map(x=>option(x.value,x.label,x.value===value)).join('')}
function cbsOptions(value=''){return D.cbs.map(x=>option(x.code,`${x.code} ${x.name}`,x.code===value)).join('')}
function contractOptions(value=''){return D.contracts.filter(contractApproved).map(c=>option(c.id,`${c.number} · ${c.name}`,c.id===value)).join('')}
function supplierOptions(value=''){return D.suppliers.map(s=>option(s.name,s.name,s.name===value)).join('')}

function modalBudget(){openModal('Nova alteração orçamentária',`<div class="form-grid">${field('Tipo',select('fType',[{value:'suplementacao',label:'Suplementação'},{value:'reducao',label:'Redução'},{value:'transferencia',label:'Transferência'},{value:'reclassificacao',label:'Reclassificação'}]))}${field('EAP origem / linha',`<select id="fWbs">${wbsOptions()}</select>`)}${field('CBS origem / linha',`<select id="fCbs">${cbsOptions()}</select>`)}${field('EAP destino (transferência)',`<select id="fWbsTo">${wbsOptions()}</select>`)}${field('CBS destino (transferência)',`<select id="fCbsTo">${cbsOptions()}</select>`)}${field('Valor',input('fAmount','0','number','step="0.01" min="0"'))}${field('Descrição',input('fDesc','Nova alteração'),false)}${field('Status',select('fStatus',[{value:'rascunho',label:'Rascunho'},{value:'em_aprovacao',label:'Em aprovação'}]))}</div><div class="info-box">Suplementação soma verba; redução subtrai. Transferência/reclassificação gera automaticamente saída e entrada de mesmo valor.</div><div class="modal-actions">${btn('Salvar','saveBudgetAdj',true)}</div>`) }
function modalCost(){openModal('Novo custo direto',`<div class="form-grid">${field('Data',input('cDate',todayISO(),'date'))}${field('EAP',`<select id="cWbs">${wbsOptions('06')}</select>`)}${field('CBS',`<select id="cCbs">${cbsOptions('ADM')}</select>`)}${field('Categoria',input('cCat','Administração local'))}${field('Descrição',input('cDesc','Novo custo'),true)}${field('Valor',input('cAmount','0','number','step="0.01"'))}${field('Status',select('cStatus',[{value:'rascunho',label:'Rascunho'},{value:'em_aprovacao',label:'Em aprovação'}]))}</div><div class="modal-actions">${btn('Salvar','saveCost',true)}</div>`)}
function modalContract(){openModal('Novo contrato',`<div class="form-grid">${field('Número',input('ctNumber','CT-'+String(D.contracts.length+1).padStart(3,'0')))}${field('Fornecedor',`<select id="ctSupplier">${supplierOptions()}</select>`)}${field('Objeto',input('ctName','Novo contrato'),true)}${field('Início',input('ctStart',todayISO(),'date'))}${field('Fim',input('ctEnd','2027-06-30','date'))}${field('EAP',`<select id="ctWbs">${wbsOptions()}</select>`)}${field('CBS',`<select id="ctCbs">${cbsOptions('SUB')}</select>`)}${field('Valor',input('ctAmount','0','number','step="0.01"'))}${field('Status',select('ctStatus',[{value:'rascunho',label:'Rascunho'},{value:'em_aprovacao',label:'Em aprovação'}]))}</div><div class="modal-actions">${btn('Salvar','saveContract',true)}</div>`)}
function modalAmendment(c){openModal('Novo aditivo / supressão',`<div class="form-grid">${field('Contrato',input('adContract',c.id,'text','readonly'))}${field('Tipo',select('adType',[{value:'acrescimo',label:'Acréscimo'},{value:'supressao',label:'Supressão'},{value:'prazo',label:'Prazo'},{value:'reajuste',label:'Reajuste'}]))}${field('Descrição',input('adDesc','Novo aditivo'),true)}${field('Valor (+/-)',input('adAmount','0','number','step="0.01"'))}${field('Status',select('adStatus',[{value:'rascunho',label:'Rascunho'},{value:'em_aprovacao',label:'Em aprovação'}]))}</div><div class="modal-actions">${btn('Salvar','saveAmendment',true)}</div>`)}
function modalMeasurement(editId){const m=editId?D.measurements.find(x=>x.id===editId):null;const title=m?'Editar medição':'Nova medição';const numero=m?m.number:((D.measurements.filter(x=>x.contract===($('#mContract')?.value||'')).length||0)+1);const campos=`<div class="form-grid">${field('Contrato',`<select id="mContract">${contractOptions(m?.contract)}</select>`)}${field('Número',input('mNumber',m?.number||numero,'number','readonly'))}${field('Mês referência',input('mPeriod',m?.mes_referencia||todayISO().slice(0,7),'month'))}${field('Data início',input('mStart',m?.data_inicio||todayISO(),'date'))}${field('Data fim',input('mEnd',m?.data_fim||todayISO(),'date'))}${field('Valor',input('mAmount',m?.amount||0,'number','step="0.01"'))}${field('Fechada',select('mFechada',[{value:'false',label:'Não'},{value:'true',label:'Sim'}],m?.fechada?'true':'false'))}${field('Status',select('mStatus',[{value:'rascunho',label:'Rascunho'},{value:'em_aprovacao',label:'Em aprovação'},{value:'aprovada',label:'Aprovada'}],m?.status||'rascunho'))}</div>`;openModal(title,campos+`<div class="modal-actions">${btn('Salvar','saveMeasurement',true)}</div>`)}
function modalInvoice(editId){const n=editId?D.invoices.find(x=>x.id===editId):null;const title=n?'Editar nota fiscal':'Nova nota fiscal';const sources=D.measurements.filter(m=>m.status==='aprovada').map(m=>({value:m.id,label:`Medição ${m.id} · ${m.contract} · ${moneyM(m.amount)}`}));(D.purchaseOrders||[]).filter(poApproved).forEach(p=>sources.push({value:p.id,label:`Pedido ${p.number} · ${p.supplier} · ${moneyM(p.amount)}`}));sources.unshift({value:'',label:'Custo direto / sem origem vinculada'});const campos=`<div class="form-grid">${field('Número',input('nfNumber',n?.number||String(5000+D.invoices.length)))}${field('Série',input('nfSerie',n?.serie||'001'))}${field('Fornecedor',`<select id="nfSupplier">${supplierOptions(n?.supplier)}</select>`)}${field('CNPJ Fornecedor',input('nfCnpj',n?.cnpj_fornecedor||''))}${field('Data',input('nfDate',n?.data||n?.date||todayISO(),'date'))}${field('Categoria',input('nfCategoria',n?.categoria||''))}${field('Responsável',input('nfResponsavel',n?.responsavel||''))}${field('Valor',input('nfAmount',n?.amount||0,'number','step="0.01"'))}${field('Origem',select('nfSource',sources,n?.source||''))}${field('Observações',textarea('nfObs',n?.observacoes||''),true)}${field('Status',select('nfStatus',[{value:'rascunho',label:'Rascunho'},{value:'conferida',label:'Conferida'},{value:'em_aprovacao',label:'Em aprovação'},{value:'aprovada',label:'Aprovada'},{value:'paga',label:'Paga'}],n?.status||'rascunho'))}</div>`;openModal(title,campos+`<div class="modal-actions">${btn('Salvar','saveInvoice',true)}</div>`)}
function modalPlan(){openModal('Nova atividade de planejamento',`<div class="form-grid">${field('EAP',`<select id="pWbs">${wbsOptions()}</select>`)}${field('Atividade',input('pActivity','Nova atividade'),true)}${field('Início',input('pStart',todayISO(),'date'))}${field('Fim',input('pEnd','2026-09-30','date'))}${field('Responsável',input('pOwner','Planejamento'))}${field('Planejado %',input('pPlanned','0','number','min="0" max="100"'))}${field('Real %',input('pActual','0','number','min="0" max="100"'))}${field('Crítica',select('pCritical',[{value:'false',label:'Não'},{value:'true',label:'Sim'}]))}</div><div class="modal-actions">${btn('Salvar','savePlan',true)}</div>`)}
function modalWeeklyPlan(){openModal('Novo item da programação semanal',`<div class="form-grid">${field('EAP',`<select id="wpWbs">${wbsOptions()}</select>`)}${field('Atividade',input('wpActivity','Nova meta semanal'),true)}${field('Responsável',input('wpOwner','Produção'))}${field('Quantidade planejada',input('wpPlanned','0','number','step="0.001"'))}${field('Quantidade realizada',input('wpActual','0','number','step="0.001"'))}${field('Unidade',input('wpUnit','un'))}</div><div class="modal-actions">${btn('Salvar','saveWeeklyPlan',true)}</div>`) }
function modalFortnightPlan(){openModal('Novo item da programação quinzenal',`<div class="form-grid">${field('EAP',`<select id="fpWbs">${wbsOptions()}</select>`)}${field('Entrega',input('fpActivity','Nova entrega quinzenal'),true)}${field('Responsável',input('fpOwner','Produção'))}${field('Prazo',input('fpDue',todayISO(),'date'))}</div><div class="modal-actions">${btn('Salvar','saveFortnightPlan',true)}</div>`) }
function modalRestriction(){openModal('Nova restrição',`<div class="form-grid">${field('EAP',`<select id="resWbs">${wbsOptions()}</select>`)}${field('Restrição',input('resTitle','Nova restrição'),true)}${field('Responsável',input('resOwner','Engenharia'))}${field('Prazo',input('resDue',todayISO(),'date'))}</div><div class="modal-actions">${btn('Salvar','saveRestriction',true)}</div>`)}
function modalRdo(){openModal('Novo RDO',`<div class="form-grid">${field('Data',input('rDate',todayISO(),'date'))}${field('Local da obra',input('rLocal',''))}</div><div class="info-box">O RDO será criado em rascunho e aberto no formulário completo. Depois disso, cada campo é salvo automaticamente.</div><div class="modal-actions">${btn('Criar e abrir RDO','saveRdo',true)}</div>`)}
function modalDocument(editId){const d=editId?D.documents.find(x=>x.id===editId):null;const title=d?'Editar documento':'Novo documento';state.editingDocument=editId||null;openModal(title,`<div class="form-grid">${field('Título',input('dTitulo',d?.titulo||'Novo documento'),true)}${field('Categoria',input('dCategoria',d?.categoria||'Geral'))}${field('Arquivo',input('dArquivo',d?.arquivo_nome||''))}${field('URL',input('dUrl',d?.url||''))}${field('Valor orçado',input('dValor',d?.valor_orcamento||'0','number','step="0.01"'))}${field('Data cronograma',input('dDataCron',d?.data_cronograma||'','date'))}</div><div class="modal-actions">${btn('Salvar','saveDocument',true)}</div>`)}
function modalTask(editId){const t=editId?D.tasks.find(x=>x.id===editId):null;const title=editId?'Editar tarefa':'Nova tarefa';state.editingTask=editId||null;openModal(title,`<div class="form-grid">${field('Assunto',input('tSubject',t?.subject||'Nova pendência'),true)}${field('Descrição',textarea('tDescription',t?.description||''),true)}${field('Responsável',input('tOwner',t?.owner||'Engenharia'))}${field('Setor',`<select id="tSector">${option('Suprimentos','Suprimentos',t?.sector==='Suprimentos')}${option('Transporte','Transporte',t?.sector==='Transporte')}${option('Planejamento','Planejamento',t?.sector==='Planejamento')}${option('Administração','Administração',t?.sector==='Administração')}${option('Segurança','Segurança',t?.sector==='Segurança')}</select>`)}${field('Criador',input('tCreator',t?.creator||'Jonacir'))}${field('Lançamento',input('tLaunchDate',t?.launchDate||todayISO(),'date'))}${field('Prazo',input('tDue',t?.due||todayISO(),'date'))}${field('Prioridade',`<select id="tPriority">${option('baixa','Baixa',t?.priority==='baixa')}${option('media','Média',t?.priority==='media')}${option('alta','Alta',t?.priority==='alta')}</select>`)}${field('Origem',input('tOrigin',t?.origin||'pauta'))}</div><div class="modal-actions">${btn('Salvar','saveTask',true)}</div>`)}
function modalOccurrence(editId){const o=editId?D.occurrences.find(x=>x.id===editId):null;const title=editId?'Editar ocorrência':'Nova ocorrência';state.editingOccurrence=editId||null;openModal(title,`<div class="form-grid">${field('Data',input('oDate',o?.date||todayISO(),'date'))}${field('Tipo',input('oType',o?.type||'Operacional'))}${field('Gravidade',`<select id="oSeverity">${option('baixa','Baixa',o?.severity==='baixa')}${option('media','Média',o?.severity==='media')}${option('alta','Alta',o?.severity==='alta')}${option('critica','Crítica',o?.severity==='critica')}</select>`)}${field('Responsável',input('oOwner',o?.owner||'Engenharia'))}${field('Registrado por',input('oRegisteredBy',o?.registeredBy||'Jonacir'))}${field('Vinculado a',`<select id="oContractId">${option('','Não vinculado',!o?.contractId)}${D.people.map(p=>`<option value="${p.id}" ${o?.contractId===p.id?'selected':''}>${h(p.name)}</option>`).join('')}</select>`)}${field('Descrição',textarea('oDesc',o?.description||''),true)}${field('Ação tomada',textarea('oAction',o?.action||''),true)}${field('Dias de afastamento',input('oDaysAway',o?.daysAway||'0','number','min="0"'))}</div><div class="modal-actions">${btn('Salvar','saveOccurrence',true)}</div>`)}
function modalMeeting(editId){const m=editId?D.meetings.find(x=>x.id===editId):null;const title=m?'Editar reunião':'Nova reunião';state.editingMeeting=editId||null;openModal(title,`<div class="form-grid">${field('Data',input('mtDate',m?.date||todayISO(),'date'))}${field('Hora início',input('mtHoraInicio',m?.hora_inicio||'09:00','time'))}${field('Hora fim',input('mtHoraFim',m?.hora_fim||'10:30','time'))}${field('Título',input('mtTitulo',m?.titulo||'Reunião semanal de produção'),true)}${field('Local',input('mtLocal',m?.local||'Sala reunião obra'))}${field('Status',select('mtStatus',[{value:'aberta',label:'Aberta'},{value:'realizada',label:'Realizada'},{value:'cancelada',label:'Cancelada'}],m?.status||'aberta'))}</div><div class="modal-actions">${btn('Salvar','saveMeeting',true)}</div>`)}
function modalEquipment(editId){const e=editId?D.equipment.find(x=>x.id===editId):null;const title=editId?'Editar equipamento':'Novo equipamento';state.editingEquipment=editId||null;openModal(title,`<div class="form-grid">${field('Prefixo',input('ePrefix',e?.prefix||'TESTE-EQP-'+String(D.equipment.length+1).padStart(2,'0')),true)}${field('Tipo',input('eType',e?.type||'Equipamento'),true)}${field('Marca',input('eBrand',e?.brand||''))}${field('Modelo',input('eModel',e?.model||''))}${field('Placa',input('ePlate',e?.plate||''))}${field('Ano',input('eYear',e?.year||'','number','min="1900" max="2100"'))}${field('Categoria',`<select id="eCategory">${option('pesado','Pesado',e?.category==='pesado')}${option('leve','Leve',e?.category==='leve')}${option('especial','Especial',e?.category==='especial')}</select>`)}${field('Propriedade',`<select id="eOwner">${option('Próprio','Próprio',e?.owner==='Próprio')}${option('Locado','Locado',e?.owner==='Locado')}</select>`)}${field('Fornecedor',`<select id="eSupplier">${supplierOptions()}</select>`)}${field('Disponibilidade %',input('eAvailability',e?.availability||'100','number','min="0" max="100"'))}${field('Utilização %',input('eUtilization',e?.utilization||'0','number','min="0" max="100"'))}${field('Status',`<select id="eStatus">${option('operando','Operando',e?.status==='operando')}${option('parado','Parado',e?.status==='parado')}${option('manutencao','Manutenção',e?.status==='manutencao')}${option('disponivel','Disponível',e?.status==='disponivel')}</select>`)}${e?.id?field('Ativo',`<select id="eActive">${option('sim','Sim',e?.active==='true'||e?.active===true)}${option('nao','Não',e?.active==='false'||e?.active===false)}</select>`):''}</div><div class="modal-actions">${btn('Salvar','saveEquipment',true)}</div>`)}
function modalMaintenance(){openModal('Programar manutenção',`<div class="form-grid">${field('Equipamento',select('manEquipment',D.equipment.map(e=>({value:e.id,label:`${e.prefix} · ${e.type}`}))))}${field('Data',input('manDate',todayISO(),'date'))}${field('Tipo',input('manType','Preventiva'))}${field('Descrição',input('manDesc','Revisão programada'),true)}</div><div class="modal-actions">${btn('Salvar','saveMaintenance',true)}</div>`)}
function modalDocumentNote(docId){openModal('Adicionar nota ao documento',`<div class="form-grid">${field('Nota',textarea('dnText',''),true)}</div><div class="modal-actions">${btn('Salvar nota','saveDocumentNote-'+docId,true)}</div>`)}
function modalMeetingNote(meetingId){openModal('Adicionar nota à reunião',`<div class="form-grid">${field('Nota',textarea('mnText',''),true)}</div><div class="modal-actions">${btn('Salvar nota','saveMeetingNote-'+meetingId,true)}</div>`)}
function modalMural(){openModal('Novo aviso no mural',`<div class="form-grid">${field('Mensagem',textarea('muralText',''),true)}</div><div class="modal-actions">${btn('Publicar','saveMuralEntry',true)}</div>`)}
function modalPerson(editId){const p=editId?D.people.find(x=>x.id===editId):null;const title=editId?'Editar colaborador':'Novo colaborador';state.editingPerson=editId||null;openModal(title,`<div class="form-grid">${field('Nome',input('peName',p?.name||'COLABORADOR TESTE '+String(D.people.length+1).padStart(2,'0')),true)}${field('Empresa',input('peCompany',p?.company||'EMPRESA TESTE'))}${field('Função',`<select id="peFunction">${D.functionsCatalog.map(f=>option(f.name,f.name,f.name===p?.function)).join('')}</select>`)}${field('Tipo',`<select id="peType">${option('proprio','Próprio',p?.type==='proprio')}${option('terceiro','Terceiro',p?.type==='terceiro')}</select>`)}${field('CPF',input('peCpf',p?.cpf||'000.000.000-00'))}${field('CTPS',input('peCtps',p?.ctps||''))}${field('PIS',input('pePis',p?.pis||'000.00000.00-00'))}${field('CNH',input('peCnh',p?.cnh||''))}${field('Data de nascimento',input('peBirth',p?.birthDate||'','date'))}${field('Telefone',input('pePhone',p?.phone||'(48)99999-0000'))}${field('Endereço',input('peAddress',p?.address||'',true))}${field('Admissão',input('peAdmission',p?.admission||todayISO(),'date'))}${p?.id?field('Desligamento',input('peDischarge',p?.discharge||'','date')):''}${p?.id?field('Status',`<select id="peStatus">${option('ativo','Ativo',p?.status==='ativo')}${option('inativo','Inativo',p?.status==='inativo')}${option('afastado','Afastado',p?.status==='afastado')}</select>`):''}</div><div class="modal-actions">${btn('Salvar','savePerson',true)}</div>`)}
function modalCatalog(){if(state.cadastroTab==='atividades')return openModal('Nova atividade',`<div class="form-grid">${field('Descrição',input('catName','Nova atividade'))}${field('Unidade',input('catUnit','un'))}</div><div class="modal-actions">${btn('Salvar','saveCatalogActivity',true)}</div>`);if(state.cadastroTab==='epis')return openModal('Novo EPI',`<div class="form-grid">${field('Nome',input('catName','Novo EPI'))}${field('CA',input('catCa','TESTE-000'))}${field('Validade de uso (dias)',input('catValidity','180','number'))}</div><div class="modal-actions">${btn('Salvar','saveCatalogEpi',true)}</div>`);if(state.cadastroTab==='funcoes')return openModal('Nova função',`<div class="form-grid">${field('Nome',input('catName','Nova função'))}${field('Categoria',select('catCategory',[{value:'tecnica',label:'Técnica'},{value:'lideranca',label:'Liderança'},{value:'operacional',label:'Operacional'}]))}${field('Periodicidade viagem (dias)',input('catTravel','30','number'))}</div><div class="modal-actions">${btn('Salvar','saveCatalogFunction',true)}</div>`);if(state.cadastroTab==='fornecedores')return openModal('Novo fornecedor',`<div class="form-grid">${field('Nome',input('catName','FORNECEDOR TESTE NOVO'))}${field('CNPJ',input('catCnpj','00.000.000/0001-00'))}${field('Especialidade',input('catSpecialty','Civil'))}</div><div class="modal-actions">${btn('Salvar','saveCatalogSupplier',true)}</div>`);if(state.cadastroTab==='cbs')return openModal('Novo código CBS',`<div class="form-grid">${field('Código',input('catCode','NOVO'))}${field('Descrição',input('catName','Novo código de custo'))}</div><div class="modal-actions">${btn('Salvar','saveCatalogCbs',true)}</div>`);if(state.cadastroTab==='entregas')return openModal('Nova entrega de EPI',`<div class="form-grid">${field('Colaborador',select('entPerson',D.people.map(p=>({value:p.id,label:p.name}))))}${field('EPI',select('entEpi',D.epis.map(e=>({value:e.id,label:e.name}))))}${field('Data',input('entDate',todayISO(),'date'))}${field('Quantidade',input('entQty','1','number'))}${field('Motivo',select('entReason',[{value:'primeira_entrega',label:'Primeira entrega'},{value:'troca',label:'Troca'},{value:'danificado',label:'Danificado'},{value:'perda',label:'Perda'},{value:'vencimento',label:'Vencimento'}]))}</div><div class="modal-actions">${btn('Salvar','saveEpiDelivery',true)}</div>`)}

function bindModalActions(){
  const on=(id,fn)=>{const e=$('#'+id);if(e)e.onclick=fn};
  on('newPerson',()=>{modalPerson()});
  on('back',()=>{state.context=null;renderAll()});
  on('saveBudgetAdj',()=>{const type=$('#fType').value,status=$('#fStatus').value,desc=$('#fDesc').value.trim()||'Alteração orçamentária',value=Math.abs(num($('#fAmount').value));if(value<=0)return toast('Informe um valor maior que zero.');const group=uid('ALTG'),date=todayISO();if(['transferencia','reclassificacao'].includes(type)){const fromWbs=$('#fWbs').value,fromCbs=$('#fCbs').value,toWbs=$('#fWbsTo').value,toCbs=$('#fCbsTo').value;if(fromWbs===toWbs&&fromCbs===toCbs)return toast('Origem e destino da transferência precisam ser diferentes.');D.budgetAdjustments.push({id:uid('ALT'),group,type,wbs:fromWbs,cbs:fromCbs,description:'Saída · '+desc,delta:-value,status,date},{id:uid('ALT'),group,type,wbs:toWbs,cbs:toCbs,description:'Entrada · '+desc,delta:value,status,date});}else{const delta=type==='reducao'?-value:value;D.budgetAdjustments.push({id:uid('ALT'),group,type,wbs:$('#fWbs').value,cbs:$('#fCbs').value,description:desc,delta,status,date});}audit('orcamento','ALTERACAO_CRIADA',group,desc);closeModal();toast('Alteração registrada.');renderAll()});
  on('saveCost',()=>{const status=$('#cStatus').value;if(status==='aprovado'&&!can('custos','approve'))return toast('Seu perfil não aprova custos.');D.directCosts.push({id:uid('DC'),date:$('#cDate').value,wbs:$('#cWbs').value,cbs:$('#cCbs').value,category:$('#cCat').value,description:$('#cDesc').value,amount:num($('#cAmount').value),status});audit('custos','CUSTO_CRIADO','CUSTO',$('#cDesc').value);closeModal();toast('Custo registrado.');renderAll()});
  on('saveContract',()=>{const status=$('#ctStatus').value;if(status==='aprovado'&&!can('contratos','approve'))return toast('Seu perfil não aprova contratos.');const n=$('#ctNumber').value.trim();if(!n||D.contracts.some(c=>c.number===n))return toast('Número de contrato vazio ou duplicado.');const amount=num($('#ctAmount').value);D.contracts.push({id:n,number:n,name:$('#ctName').value,supplier:$('#ctSupplier').value,status,start:$('#ctStart').value,end:$('#ctEnd').value,retention:0,items:[{id:uid('CTI'),wbs:$('#ctWbs').value,cbs:$('#ctCbs').value,description:$('#ctName').value,qty:1,unit:'vb',unitPrice:amount,amount}]});audit('contratos','CONTRATO_CRIADO',n,$('#ctName').value);closeModal();toast('Contrato registrado.');renderAll()});
  on('saveAmendment',()=>{const status=$('#adStatus').value;if(status==='aprovado'&&!can('contratos','approve'))return toast('Seu perfil não aprova aditivos.');const contract=$('#adContract').value;const type=$('#adType').value;let amount=num($('#adAmount').value);if(type==='supressao'&&amount>0)amount=-amount;if(type==='prazo')amount=0;D.contractAmendments.push({id:uid('AD'),contract,number:D.contractAmendments.filter(a=>a.contract===contract).length+1,type,description:$('#adDesc').value,amount,status,date:todayISO()});closeModal();toast('Aditivo registrado.');renderAll()});
  on('saveMeasurement',()=>{const contract=$('#mContract').value;const amount=num($('#mAmount').value);const status=$('#mStatus').value;if(amount<=0)return toast('Informe um valor de medição maior que zero.');if(!state.editingMeasurement){const c=D.contracts.find(x=>x.id===contract);const available=contractValue(c)-measuredContract(contract);if(amount>available)return toast('Medição maior que o saldo contratual.');}if(status==='aprovada'&&!can('medicoes','approve'))return toast('Seu perfil não aprova medições.');if(state.editingMeasurement){const m=D.measurements.find(x=>x.id===state.editingMeasurement);if(m){m.contract=contract;m.mes_referencia=$('#mPeriod').value;m.data_inicio=$('#mStart').value;m.data_fim=$('#mEnd').value;m.amount=amount;m.status=status;m.fechada=$('#mFechada').value==='true';audit('medicoes','MEDICAO_EDITADA',m.id,money(amount))}}else{D.measurements.push({id:uid('BM'),number:D.measurements.filter(m=>m.contract===contract).length+1,contract,mes_referencia:$('#mPeriod').value,data_inicio:$('#mStart').value,data_fim:$('#mEnd').value,amount,status,fechada:$('#mFechada').value==='true',id_legado:'',criado_em:new Date().toISOString(),items:[]});audit('medicoes','MEDICAO_CRIADA',contract,money(amount))}state.editingMeasurement=null;closeModal();toast('Medição salva.');renderAll()});
  on('saveInvoice',()=>{const status=$('#nfStatus').value;const number=$('#nfNumber').value.trim();const supplier=$('#nfSupplier').value;const amount=num($('#nfAmount').value);if(!number)return toast('Informe o número da NF.');if(amount<=0)return toast('Informe um valor de NF maior que zero.');if(!state.editingInvoice&&D.invoices.some(n=>n.number===number&&n.supplier===supplier))return toast('Já existe NF com este número para o fornecedor.');if(state.editingInvoice){const n=D.invoices.find(x=>x.id===state.editingInvoice);if(n){n.number=number;n.serie=$('#nfSerie').value;n.supplier=supplier;n.cnpj_fornecedor=$('#nfCnpj').value;n.data=$('#nfDate').value;n.categoria=$('#nfCategoria').value;n.responsavel=$('#nfResponsavel').value;n.observacoes=$('#nfObs').value;n.amount=amount;n.status=status;n.source=$('#nfSource').value||'';audit('nfs','NF_EDITADA',n.number,money(amount))}}else{D.invoices.push({id:uid('NF'),number,serie:$('#nfSerie').value,supplier,cnpj_fornecedor:$('#nfCnpj').value,data:$('#nfDate').value,categoria:$('#nfCategoria').value,responsavel:$('#nfResponsavel').value,observacoes:$('#nfObs').value,amount,status,source:$('#nfSource').value||'',id_legado:'',criado_em:new Date().toISOString(),items:[]});audit('nfs','NF_CRIADA',number,money(amount))}state.editingInvoice=null;closeModal();toast('NF salva.');renderAll()});
  on('savePlan',()=>{D.planning.push({id:uid('P'),wbs:$('#pWbs').value,activity:$('#pActivity').value,start:$('#pStart').value,end:$('#pEnd').value,planned:num($('#pPlanned').value),actual:num($('#pActual').value),owner:$('#pOwner').value,critical:$('#pCritical').value==='true'});closeModal();toast('Atividade adicionada.');renderAll()});
  on('saveWeeklyPlan',()=>{const x={id:uid('S'),wbs:$('#wpWbs').value,activity:$('#wpActivity').value,owner:$('#wpOwner').value,plannedQty:num($('#wpPlanned').value),actualQty:num($('#wpActual').value),unit:$('#wpUnit').value,status:'em_andamento'};D.weeklyPlan.push(x);audit('planejamento','PROGRAMACAO_SEMANAL_CRIADA',x.id,x.activity);closeModal();toast('Item semanal criado.');renderAll()});
  on('saveFortnightPlan',()=>{const x={id:uid('Q'),wbs:$('#fpWbs').value,activity:$('#fpActivity').value,owner:$('#fpOwner').value,due:$('#fpDue').value,status:'aberta'};D.fortnightPlan.push(x);audit('planejamento','PROGRAMACAO_QUINZENAL_CRIADA',x.id,x.activity);closeModal();toast('Item quinzenal criado.');renderAll()});
  on('saveRestriction',()=>{D.restrictions.push({id:uid('R'),wbs:$('#resWbs').value,title:$('#resTitle').value,owner:$('#resOwner').value,due:$('#resDue').value,status:'aberta'});closeModal();toast('Restrição adicionada.');renderAll()});
  on('saveRdo',()=>{const date=$('#rDate').value;if(D.rdos.some(r=>r.date===date))return toast('Já existe RDO para esta data.');const r=rdoNormalize({id:uid('RDO'),number:(Math.max(0,...D.rdos.map(r=>num(r.number)))+1),date,status:'rascunho',location:{local:$('#rLocal').value,description:''},notes:''});D.rdos.push(r);state.context=r.id;state.rdoTab='diario';audit('rdo','RDO_CRIADO',date,'Rascunho completo criado');closeModal();toast('RDO criado. Preencha o diário completo.');renderAll()});
  on('saveDocument',()=>{const titulo=$('#dTitulo').value.trim();if(!titulo)return toast('Informe o título do documento.');const data={titulo,categoria:$('#dCategoria').value,arquivo_nome:$('#dArquivo').value,url:$('#dUrl').value,valor_orcamento:num($('#dValor').value)||null,data_cronograma:$('#dDataCron').value||null,atualizado_em:new Date().toISOString()};if(state.editingDocument){const d=D.documents.find(x=>x.id===state.editingDocument);if(d){Object.assign(d,data);audit('documentos','DOCUMENTO_EDITADO',d.id,titulo);toast('Documento atualizado.');}}else{D.documents.push({id:uid('DOC'),...data,criado_em:new Date().toISOString(),id_legado:'',notes:[]});audit('documentos','DOCUMENTO_CRIADO','DOC',titulo);toast('Documento registrado.');}closeModal();state.editingDocument=null;renderAll()});
  on('saveTask',()=>{const data={subject:$('#tSubject').value,description:$('#tDescription').value,owner:$('#tOwner').value,sector:$('#tSector').value,creator:$('#tCreator').value,launchDate:$('#tLaunchDate').value,due:$('#tDue').value,priority:$('#tPriority').value,origin:$('#tOrigin').value};if(state.editingTask){const idx=D.tasks.findIndex(t=>t.id===state.editingTask);if(idx>=0){D.tasks[idx]={...D.tasks[idx],...data};audit('tarefas','TAREFA_ATUALIZADA','TAREFA',data.subject);toast('Tarefa atualizada.');}}else{D.tasks.push({id:uid('T'),status:'aberta',completedAt:null,...data});audit('tarefas','TAREFA_CRIADA','TAREFA',data.subject);toast('Tarefa criada.');}closeModal();state.editingTask=null;renderAll()});
  on('saveOccurrence',()=>{const data={date:$('#oDate').value,type:$('#oType').value,severity:$('#oSeverity').value,description:$('#oDesc').value,action:$('#oAction').value,owner:$('#oOwner').value,registeredBy:$('#oRegisteredBy').value,contractId:$('#oContractId').value||null,daysAway:num($('#oDaysAway').value),createdAt:new Date().toISOString()};if(state.editingOccurrence){const idx=D.occurrences.findIndex(o=>o.id===state.editingOccurrence);if(idx>=0){D.occurrences[idx]={...D.occurrences[idx],...data};toast('Ocorrência atualizada.');}}else{D.occurrences.push({id:uid('O'),rdoId:null,...data});toast('Ocorrência registrada.');}closeModal();state.editingOccurrence=null;renderAll()});
  on('saveMeeting',()=>{const titulo=$('#mtTitulo').value.trim();if(!titulo)return toast('Informe o título da reunião.');const data={date:$('#mtDate').value,hora_inicio:$('#mtHoraInicio').value,hora_fim:$('#mtHoraFim').value,titulo,local:$('#mtLocal').value,status:$('#mtStatus').value,atualizado_em:new Date().toISOString()};if(state.editingMeeting){const m=D.meetings.find(x=>x.id===state.editingMeeting);if(m){Object.assign(m,data);audit('reunioes','REUNIAO_EDITADA',m.id,titulo);toast('Reunião atualizada.');}}else{D.meetings.push({id:uid('M'),number:D.meetings.length+1,...data,criado_em:new Date().toISOString(),id_legado:'',participants:[],topics:[],tasks:[]});audit('reunioes','REUNIAO_CRIADA','M',titulo);toast('Reunião registrada.');}closeModal();state.editingMeeting=null;renderAll()});
  on('saveEquipment',()=>{const data={prefix:$('#ePrefix').value,type:$('#eType').value,brand:$('#eBrand').value,model:$('#eModel').value,plate:$('#ePlate').value,year:num($('#eYear').value),category:$('#eCategory').value,owner:$('#eOwner').value,supplier:$('#eSupplier').value,availability:num($('#eAvailability').value),utilization:num($('#eUtilization').value),status:$('#eStatus').value,active:$('#eActive')?$('#eActive').value==='sim':true};if(state.editingEquipment){const idx=D.equipment.findIndex(e=>e.id===state.editingEquipment);if(idx>=0){D.equipment[idx]={...D.equipment[idx],...data};toast('Equipamento atualizado.');}}else{D.equipment.push({id:uid('E'),...data});toast('Equipamento cadastrado.');}closeModal();state.editingEquipment=null;renderAll()});
  on('saveMaintenance',()=>{D.maintenance.push({id:uid('MAN'),equipment:$('#manEquipment').value,date:$('#manDate').value,type:$('#manType').value,description:$('#manDesc').value,status:'programada'});closeModal();toast('Manutenção programada.');renderAll()});
  on('savePerson',()=>{const name=$('#peName').value.trim();if(!name)return toast('Informe o nome do colaborador.');const editId=state.editingPerson;const data={name,company:$('#peCompany').value,function:$('#peFunction').value,type:$('#peType').value,cpf:$('#peCpf').value,ctps:$('#peCtps').value,pis:$('#pePis').value,cnh:$('#peCnh').value,birthDate:$('#peBirth').value,phone:$('#pePhone').value,address:$('#peAddress').value,admission:$('#peAdmission').value,discharge:$('#peDischarge')?.value||null,status:$('#peStatus')?.value||'ativo',documents:[]};if(editId){const p=D.people.find(x=>x.id===editId);if(p){Object.assign(p,data);audit('efetivo','PESSOA_ALTERADA',editId,name);toast('Colaborador atualizado.')}}else{D.people.push({id:uid('PES'),...data});audit('efetivo','PESSOA_CRIADA','PES',name);toast('Colaborador cadastrado.')}closeModal();state.editingPerson=null;renderAll()});
  on('saveCatalogActivity',()=>{D.activitiesCatalog.push({id:uid('AT'),description:$('#catName').value,unit:$('#catUnit').value,active:true});closeModal();renderAll()});
  on('saveCatalogEpi',()=>{D.epis.push({id:uid('EPI'),name:$('#catName').value,ca:$('#catCa').value,validityDays:num($('#catValidity').value),active:true});closeModal();renderAll()});
  on('saveCatalogFunction',()=>{D.functionsCatalog.push({id:uid('FN'),name:$('#catName').value,category:$('#catCategory').value,travelDays:num($('#catTravel').value)});closeModal();renderAll()});
  on('saveCatalogSupplier',()=>{D.suppliers.push({id:uid('F'),name:$('#catName').value,cnpj:$('#catCnpj').value,specialty:$('#catSpecialty').value,active:true});closeModal();renderAll()});
  on('saveCatalogCbs',()=>{const code=$('#catCode').value.trim().toUpperCase();if(!code||D.cbs.some(c=>c.code===code))return toast('Código CBS inválido ou duplicado.');D.cbs.push({code,name:$('#catName').value});audit('cadastro','CBS_CRIADO',code,$('#catName').value);closeModal();renderAll()});
  on('saveEap',()=>{const code=$('#eapCode').value.trim();if(!code||D.wbs.some(w=>w.code===code))return toast('Código EAP inválido ou duplicado.');const item={id:code,parent:$('#eapParent').value||null,code,name:$('#eapName').value,planned:num($('#eapPlanned').value),progress:num($('#eapActual').value)};D.wbs.push(item);audit('eap','EAP_CRIADA',code,item.name);closeModal();toast('Item EAP criado.');renderAll()});
  on('savePurchaseRequest',()=>{const id=uid('SC');const r={id,number:'SC-'+String(D.purchaseRequests.length+1).padStart(3,'0'),wbs:$('#prWbs').value,cbs:$('#prCbs').value,description:$('#prDesc').value,qty:num($('#prQty').value),unit:$('#prUnit').value,estimated:num($('#prEstimated').value),status:'em_cotacao',owner:$('#prOwner').value,date:todayISO()};D.purchaseRequests.push(r);audit('suprimentos','SOLICITACAO_CRIADA',r.number,r.description);closeModal();toast('Solicitação criada.');renderAll()});
  on('savePurchaseQuote',()=>{const q={id:uid('COT'),request:$('#pqRequest').value,supplier:$('#pqSupplier').value,amount:num($('#pqAmount').value),leadDays:num($('#pqLead').value),payment:$('#pqPayment').value,selected:false};D.purchaseQuotes.push(q);audit('suprimentos','COTACAO_CRIADA',q.id,q.supplier);closeModal();toast('Cotação registrada.');renderAll()});
  on('saveReceipt',()=>{const po=D.purchaseOrders.find(x=>x.number===$('#recOrder').value);if(!po)return toast('Pedido não encontrado.');const amount=num($('#recAmount').value),saldo=poBalance(po);if(amount<=0)return toast('Informe um valor recebido maior que zero.');if(amount>saldo+0.01)return toast('Recebimento ultrapassa o saldo do pedido.');const r={id:uid('REC'),order:po.id,date:$('#recDate').value,description:$('#recDesc').value,amount,owner:$('#recOwner').value,status:'recebido'};D.receipts.push(r);const recebido=poReceivedAmount(po.id);po.status=recebido>=po.amount-0.01?'recebido':'parcialmente_recebido';audit('suprimentos','RECEBIMENTO_REGISTRADO',po.number,`${r.description} · ${money(amount)}`);closeModal();toast(po.status==='recebido'?'Pedido totalmente recebido.':'Recebimento parcial registrado.');renderAll()});
  on('saveEpiDelivery',()=>{D.epiDeliveries.push({id:uid('ENT'),person:$('#entPerson').value,epi:$('#entEpi').value,date:$('#entDate').value,qty:num($('#entQty').value),reason:$('#entReason').value,signed:true});closeModal();renderAll()});
  on('saveRdoExtra',()=>{const r=rdoSelected();if(!r)return;r.activities.push({id:uid('RAT'),catalogId:'',description:$('#raDesc').value,location:$('#raLocal').value,qty:num($('#raQty').value),unit:$('#raUnit').value,status:'andamento',wbs:$('#raWbs').value});persist();closeModal();renderAll()});
  on('saveRdoPaused',()=>{const r=rdoSelected();if(!r)return;r.pausedActivities.push({id:uid('RAP'),description:$('#rpDesc').value,reason:$('#rpReason').value});persist();closeModal();renderAll()});
  on('saveRdoEvent',()=>{const r=rdoSelected();if(!r)return;const ev={id:uid('REV'),type:$('#reType').value,severity:$('#reSeverity').value,description:$('#reDesc').value,action:$('#reAction').value};($('#reKind').value==='safety'?r.safetyEvents:r.environmentEvents).push(ev);persist();closeModal();renderAll()});
  on('clearRdoSign',()=>{const c=$('#rdoSignCanvas');c?.getContext('2d').clearRect(0,0,c.width,c.height)});
  on('saveRdoSign',()=>{const r=rdoSelected(),c=$('#rdoSignCanvas'),slot=$('#rdoSignSlot')?.value;if(!r||!c||!slot)return;r.signatures[slot]=c.toDataURL('image/png');persist();closeModal();toast('Assinatura registrada.');renderAll()});
  Object.keys(window).filter(k=>k.startsWith('saveDocumentNote-')).forEach(k=>delete window[k]);
  for(const d of D.documents){on('addDocumentNote-'+d.id,()=>{modalDocumentNote(d.id)});on('saveDocumentNote-'+d.id,()=>{const texto=$('#dnText').value.trim();if(!texto)return toast('Informe o texto da nota.');D.documentNotes.push({id:uid('DN'),document:d.id,texto,autor:state.profile.label,criado_em:new Date().toISOString()});audit('documentos','NOTA_ADICIONADA',d.id,'Nota ao documento '+d.titulo);closeModal();toast('Nota adicionada.');renderAll()});}
  Object.keys(window).filter(k=>k.startsWith('deleteMeeting')).forEach(k=>delete window[k]);
  on('addDocumentNote',()=>{const docId=state.context;if(docId)modalDocumentNote(docId)});
  Object.keys(window).filter(k=>k.startsWith('saveMeetingNote-')).forEach(k=>delete window[k]);
  for(const m of D.meetings){on('addMeetingNote-'+m.id,()=>{modalMeetingNote(m.id)});on('saveMeetingNote-'+m.id,()=>{const texto=$('#mnText').value.trim();if(!texto)return toast('Informe o texto da nota.');D.meetingNotes.push({id:uid('MN'),reuniao_id:m.id,texto,autor:state.profile.label,criado_em:new Date().toISOString()});audit('reunioes','NOTA_ADICIONADA',m.id,'Nota à reunião '+m.titulo);closeModal();toast('Nota adicionada.');renderAll()});}
  on('addMeetingNote',()=>{const meetingId=state.context;if(meetingId)modalMeetingNote(meetingId)});
  on('newMuralEntry',()=>{modalMural()});
  on('saveMuralEntry',()=>{const texto=$('#muralText').value.trim();if(!texto)return toast('Informe a mensagem.');D.mural.push({id:uid('MRL'),texto,autor:state.profile.label,criado_em:new Date().toISOString()});audit('reunioes','MURAL_ENTRADA_CRIADA','MRL',texto.substring(0,50));closeModal();toast('Aviso publicado.');renderAll()});
}

function bindPage(){
  const on=(id,fn)=>{const e=$('#'+id);if(e)e.onclick=fn};
  on('newBudgetAdj',()=>requirePerm('orcamento','create')&&modalBudget());on('newCost',()=>requirePerm('custos','create')&&modalCost());on('newContract',()=>requirePerm('contratos','create')&&modalContract());on('newMeasurement',()=>requirePerm('medicoes','create')&&modalMeasurement());on('newInvoice',()=>requirePerm('nfs','create')&&modalInvoice());on('newPlanActivity',()=>requirePerm('planejamento','create')&&modalPlan());on('newWeeklyPlan',()=>requirePerm('planejamento','create')&&modalWeeklyPlan());on('newFortnightPlan',()=>requirePerm('planejamento','create')&&modalFortnightPlan());on('newRestriction',()=>requirePerm('planejamento','create')&&modalRestriction());on('newRdo',()=>requirePerm('rdo','create')&&modalRdo());on('newDocument',()=>requirePerm('documentos','create')&&modalDocument());on('newTask',()=>requirePerm('tarefas','create')&&modalTask());on('newOccurrence',()=>requirePerm('ocorrencias','create')&&modalOccurrence());on('newMeeting',()=>requirePerm('reunioes','create')&&modalMeeting());on('newEquipment',()=>requirePerm('equipamentos','create')&&modalEquipment());on('newMaintenance',()=>requirePerm('equipamentos','create')&&modalMaintenance());on('newPerson',()=>requirePerm('efetivo','create')&&modalPerson());on('newCatalogRecord',()=>requirePerm('cadastro','create')&&modalCatalog());on('newEap',()=>requirePerm('orcamento','edit')&&modalEap());on('newPurchaseRequest',()=>requirePerm('suprimentos','create')&&modalPurchaseRequest());on('newPurchaseQuote',()=>requirePerm('suprimentos','create')&&modalPurchaseQuote());on('refreshBrain',()=>{audit('brain','ANALISE_ATUALIZADA','TESTE','Análise local recalculada.');renderAll()});
  on('backContracts',()=>{state.context=null;renderAll()});on('backRdo',()=>{state.context=null;renderAll()});on('backDocuments',()=>{state.context=null;renderAll()});on('backMeetings',()=>{state.context=null;renderAll()});
  on('newAmendment',()=>{const c=D.contracts.find(x=>x.id===state.context);if(c&&requirePerm('contratos','edit'))modalAmendment(c)});on('approveContract',()=>{const c=D.contracts.find(x=>x.id===state.context);if(c&&requirePerm('contratos','approve')){c.status='aprovado';audit('contratos','CONTRATO_APROVADO',c.number,c.name);toast('Contrato aprovado e verba comprometida.');renderAll()}});on('newRevision',()=>{const d=D.documents.find(x=>x.id===state.context);if(d&&requirePerm('documentos','edit'))modalRevision(d)});on('newMeetingTopic',()=>{const m=D.meetings.find(x=>x.id===state.context);if(m&&requirePerm('reunioes','edit'))modalMeetingTopic(m)});
  on('printRdo',()=>window.print());on('rdoCopyText',()=>{const r=rdoSelected();if(r)navigator.clipboard?.writeText(rdoText(r)).then(()=>toast('Texto do RDO copiado.')).catch(()=>toast('Não foi possível copiar.'))});on('rdoCopyPrevious',()=>copyPreviousRdo());on('rdoFinalize',()=>finalizeRdo());on('rdoDelete',()=>deleteRdo());on('rdoAddActivity',()=>modalRdoExtraActivity());on('rdoAddPaused',()=>modalRdoPaused());on('rdoAddSafety',()=>modalRdoEvent('safety'));on('rdoAddEnvironment',()=>modalRdoEvent('environment'));on('rdoAddPhoto',()=>$('#rdoPhotoInput')?.click());on('rdoSignApontador',()=>openRdoSignature('apontador'));on('rdoSignFiscal',()=>openRdoSignature('fiscal'));on('rdoCalPrev',()=>shiftRdoCalendar(-1));on('rdoCalNext',()=>shiftRdoCalendar(1));on('rdoGoWorkforce',()=>navigate('efetivo'));on('rdoGoEquipment',()=>navigate('equipamentos'));on('rdoGoCatalog',()=>navigate('cadastro'));on('printExecutive',()=>window.print());
  on('csvFinancial',()=>{const rows=[['EAP','CBS','Original','Alterações','Atual','Comprometido','Realizado','Disponível'],...budgetRows().map(r=>[wbsName(r.wbs),cbsName(r.cbs),r.original,r.adj,r.current,r.commitment,r.realized,r.available])];downloadCsv('buildly-financeiro.csv',rows)});
  on('csvRdo',()=>downloadCsv('buildly-rdos.csv',[['RDO','Data','Clima manhã','Clima tarde','Condição','Efetivo','Equipamentos','Produção'],...D.rdos.map(r=>[r.number,r.date,r.weatherMorning,r.weatherAfternoon,r.condition,r.workforce,r.equipment,r.progress])]));
  $$('[data-open-contract]').forEach(r=>r.onclick=()=>{state.page='contratos';state.context=r.dataset.openContract;renderAll()});$$('[data-contract]').forEach(r=>r.onclick=()=>{state.page='contratos';state.context=r.dataset.contract;renderAll()});$$('[data-rdo]').forEach(r=>r.onclick=()=>{state.page='rdo';state.context=r.dataset.rdo;renderAll()});$$('[data-rdo-date]').forEach(r=>r.onclick=()=>{const date=r.dataset.rdoDate;if(r.dataset.rdo){state.page='rdo';state.context=r.dataset.rdo}else if(can('rdo','create')){const newRdo=rdoNormalize({id:uid('RDO'),number:(Math.max(0,...D.rdos.map(x=>num(x.number)))+1),date,status:'rascunho',location:{local:'',description:''},notes:''});D.rdos.push(newRdo);state.page='rdo';state.context=newRdo.id;audit('rdo','RDO_CRIADO',date,'Criado do calendário');}else toast('Sem permissão para criar RDO.');renderAll()});$$('[data-doc]').forEach(r=>r.onclick=()=>{state.page='documentos';state.context=r.dataset.doc;renderAll()});$$('[data-meeting]').forEach(r=>r.onclick=()=>{state.page='reunioes';state.context=r.dataset.meeting;renderAll()});
  $$('[data-tab-group]').forEach(b=>b.onclick=()=>{if(b.dataset.tabGroup==='planning')state.planningTab=b.dataset.tab;if(b.dataset.tabGroup==='cadastro')state.cadastroTab=b.dataset.tab;if(b.dataset.tabGroup==='wbs')state.wbsTab=b.dataset.tab;if(b.dataset.tabGroup==='procurement')state.procurementTab=b.dataset.tab;if(b.dataset.tabGroup==='rdo')state.rdoTab=b.dataset.tab;if(b.dataset.tabGroup==='rdoSummary')state.rdoSummaryMode=b.dataset.tab;renderAll()});
  $$('[id^="alert-"]').forEach(b=>b.onclick=()=>{const id=b.id.replace('alert-','');const a=D.alerts.find(x=>x.id===id);if(a&&requirePerm('alertas','edit')){a.read=!a.read;renderAll()}});
  $$('[data-action]').forEach(b=>b.onclick=()=>handleAction(b.dataset.action));
  bindRdoFields();
}

function setObjPath(obj,path,value){const parts=path.split('.');let t=obj;for(let i=0;i<parts.length-1;i++){t[parts[i]]=t[parts[i]]||{};t=t[parts[i]]}t[parts.at(-1)]=value}
function bindRdoFields(){const r=rdoSelected();if(!r||state.page!=='rdo')return;const editable=can('rdo','edit')||can('rdo','create');if(!editable)return;$$('[data-rdo-field]').forEach(el=>{const save=()=>{let v=el.type==='number'?num(el.value):el.value;if(el.dataset.rdoField==='date'&&D.rdos.some(x=>x.id!==r.id&&x.date===v)){toast('Já existe RDO nesta data.');el.value=r.date;return}setObjPath(r,el.dataset.rdoField,v);if(el.dataset.rdoField==='dssDetail.theme')r.dss=v;persist()};el.onchange=save;if(el.tagName==='TEXTAREA')el.onblur=save});$$('[data-rdo-att]').forEach(el=>el.onchange=()=>{let a=r.attendance.find(x=>x.person===el.dataset.rdoAtt);if(!a){a={person:el.dataset.rdoAtt,status:'falta',normal:0,extra:0,obs:''};r.attendance.push(a)}a[el.dataset.key]=el.type==='number'?num(el.value):el.value;persist();renderAll()});$$('[data-rdo-equip]').forEach(el=>el.onchange=()=>{let x=r.equipmentUse.find(v=>v.equipment===el.dataset.rdoEquip);if(!x){x={equipment:el.dataset.rdoEquip,active:false,operator:'',status:'operando',hoursOperating:0,hoursStopped:0,reason:'',horimeterStart:'',horimeterEnd:''};r.equipmentUse.push(x)}x[el.dataset.key]=el.type==='checkbox'?el.checked:(el.type==='number'?num(el.value):el.value);persist();renderAll()});$$('[data-rdo-activity-toggle]').forEach(el=>el.onchange=()=>{const id=el.dataset.rdoActivityToggle,cat=D.activitiesCatalog.find(a=>a.id===id),i=r.activities.findIndex(a=>a.catalogId===id);if(el.checked&&i<0)r.activities.push({id:uid('RAT'),catalogId:id,description:cat.description,location:'',qty:0,unit:cat.unit,status:'andamento',wbs:''});if(!el.checked&&i>=0)r.activities.splice(i,1);persist();renderAll()});$$('[data-rdo-act]').forEach(el=>el.onchange=()=>{const id=el.dataset.rdoAct,cat=D.activitiesCatalog.find(a=>a.id===id);let a=r.activities.find(x=>x.catalogId===id);if(!a){a={id:uid('RAT'),catalogId:id,description:cat.description,location:'',qty:0,unit:cat.unit,status:'andamento',wbs:''};r.activities.push(a)}a[el.dataset.key]=el.type==='number'?num(el.value):el.value;persist();renderAll()});$$('[data-rdo-photo]').forEach(el=>el.onchange=()=>{const f=r.photos[num(el.dataset.rdoPhoto)];if(f){f[el.dataset.key]=el.value;persist()}});$$('[data-rdo-parado]').forEach(el=>el.onchange=()=>{const key=el.dataset.rdoParado;if(!r.paradosReasons)r.paradosReasons={};r.paradosReasons[key]=el.value;persist()});const photo=$('#rdoPhotoInput');if(photo)photo.onchange=e=>{const file=e.target.files?.[0];if(file)addRdoPhoto(file,r);e.target.value=''};}
function copyPreviousRdo(){const r=rdoSelected();if(!r)return;const prev=D.rdos.filter(x=>x.id!==r.id&&x.date<r.date).sort((a,b)=>b.date.localeCompare(a.date))[0];if(!prev)return toast('Não há diário anterior.');const p=rdoNormalize(prev);r.location=clone(p.location);r.climate=clone(p.climate);r.journey=clone(p.journey);r.dssDetail={time:p.dssDetail.time,instructor:p.dssDetail.instructor,theme:''};r.attendance=clone(p.attendance);r.equipmentUse=clone(p.equipmentUse);r.activities=[];r.pausedActivities=[];r.safetyEvents=[];r.environmentEvents=[];r.photos=[];r.notes='';persist();toast('Estrutura copiada do último diário; produção, eventos, fotos e observações foram zerados.');renderAll()}
function finalizeRdo(){const r=rdoSelected();if(!r||!requirePerm('rdo','edit'))return;const missing=[];if(!r.date)missing.push('data');if(!r.dssDetail.theme)missing.push('DSS');if(!r.activities.some(a=>a.status!=='nao_executada'))missing.push('atividade');if(!r.responsible)missing.push('apontador');if(missing.length)return toast('Preencha antes de emitir: '+missing.join(', '));r.status='emitido';r.workforce=rdoAttendanceCount(r);r.equipment=rdoEquipCount(r);r.progress=r.activities.filter(a=>a.status!=='nao_executada').map(a=>a.description).join('; ');audit('rdo','RDO_EMITIDO',String(r.number),r.progress);persist();toast('RDO emitido.');renderAll()}
function deleteRdo(){const r=rdoSelected();if(!r||!requirePerm('rdo','delete'))return;if(!confirm(`Excluir RDO ${String(r.number).padStart(3,'0')} da demonstração?`))return;D.rdos.splice(D.rdos.findIndex(x=>x.id===r.id),1);state.context=null;persist();renderAll()}
function modalRdoExtraActivity(){openModal('Atividade avulsa do RDO',`<div class="form-grid">${field('Descrição',input('raDesc',''))}${field('EAP',`<select id="raWbs">${rdoWbsOptions()}</select>`)}${field('Local',input('raLocal',''))}${field('Quantidade',input('raQty','0','number','step="0.001"'))}${field('Unidade',input('raUnit','un'))}</div><div class="modal-actions">${btn('Adicionar','saveRdoExtra',true)}</div>`)}
function modalRdoPaused(){openModal('Atividade paralisada',`<div class="form-grid">${field('Atividade',input('rpDesc',''))}${field('Justificativa',textarea('rpReason',''),true)}</div><div class="modal-actions">${btn('Adicionar','saveRdoPaused',true)}</div>`)}
function modalRdoEvent(kind){openModal(kind==='safety'?'Evento de Segurança':'Evento de Meio Ambiente',`<div class="form-grid">${field('Tipo',input('reType',kind==='safety'?'Condição insegura':'Evento ambiental'))}${field('Gravidade',select('reSeverity',[{value:'baixa',label:'Baixa'},{value:'media',label:'Média'},{value:'alta',label:'Alta'},{value:'critica',label:'Crítica'}]))}${field('Descrição',textarea('reDesc',''),true)}${field('Ação tomada',textarea('reAction',''),true)}<input type="hidden" id="reKind" value="${kind}"></div><div class="modal-actions">${btn('Adicionar','saveRdoEvent',true)}</div>`)}
function openRdoSignature(slot){openModal(slot==='apontador'?'Assinatura do Apontador':'Assinatura da Fiscalização / Cliente',`<canvas id="rdoSignCanvas" width="520" height="180" class="rdo-sign-canvas"></canvas><input type="hidden" id="rdoSignSlot" value="${slot}"><div class="modal-actions">${btn('Limpar','clearRdoSign')}${btn('Salvar assinatura','saveRdoSign',true)}</div>`);setTimeout(()=>{const c=$('#rdoSignCanvas');if(!c)return;const ctx=c.getContext('2d');ctx.lineWidth=2.2;ctx.lineCap='round';let draw=false;c.onpointerdown=e=>{draw=true;const r=c.getBoundingClientRect();ctx.beginPath();ctx.moveTo((e.clientX-r.left)*c.width/r.width,(e.clientY-r.top)*c.height/r.height)};c.onpointermove=e=>{if(!draw)return;const r=c.getBoundingClientRect();ctx.lineTo((e.clientX-r.left)*c.width/r.width,(e.clientY-r.top)*c.height/r.height);ctx.stroke()};c.onpointerup=c.onpointerleave=()=>draw=false},0)}
function addRdoPhoto(file,r){if(r.photos.length>=20)return toast('Limite de 20 fotos por RDO.');if(file.size>12*1024*1024)return toast('Foto muito grande. Máximo 12 MB.');const fr=new FileReader();fr.onload=()=>{const img=new Image();img.onload=()=>{const max=1280,scale=Math.min(1,max/Math.max(img.width,img.height)),c=document.createElement('canvas');c.width=Math.round(img.width*scale);c.height=Math.round(img.height*scale);c.getContext('2d').drawImage(img,0,0,c.width,c.height);r.photos.push({id:uid('RF'),dataUrl:c.toDataURL('image/jpeg',.78),caption:'',activityId:''});persist();toast('Foto adicionada.');renderAll()};img.src=fr.result};fr.readAsDataURL(file)}
function shiftRdoCalendar(delta){const [y,m]=state.rdoCalendarAnchor.split('-').map(Number);const d=new Date(y,m-1+delta,1);state.rdoCalendarAnchor=`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`;renderAll()}

function deleteDocumentNote(noteId){if(!confirm('Remover esta nota?'))return;D.documentNotes=D.documentNotes.filter(n=>n.id!==noteId);audit('documentos','NOTA_REMOVIDA','DN',noteId);toast('Nota removida.');renderAll()}
function deleteMeetingNote(noteId){if(!confirm('Remover esta nota?'))return;D.meetingNotes=D.meetingNotes.filter(n=>n.id!==noteId);audit('reunioes','NOTA_REMOVIDA','MN',noteId);toast('Nota removida.');renderAll()}
function deleteMuralEntry(entryId){if(!confirm('Remover este aviso?'))return;D.mural=D.mural.filter(m=>m.id!==entryId);audit('reunioes','MURAL_ENTRADA_REMOVIDA','MRL',entryId);toast('Aviso removido.');renderAll()}
function handleAction(action){const parts=action.split(':'),kind=parts[0],id=parts[1];
  if(kind==='modalSelectPeople'){modalSelectPeople();return}
  if(kind==='modalSelectEquipment'){modalSelectEquipment();return}
  if(kind==='modalSelectLightVehicles'){modalSelectLightVehicles();return}
  if(kind==='modalSelectActivities'){modalSelectActivities();return}
  if(kind==='confirmPeopleSelect'){confirmPeopleSelect();return}
  if(kind==='confirmEquipmentSelect'){confirmEquipmentSelect();return}
  if(kind==='confirmVehiclesSelect'){confirmVehiclesSelect();return}
  if(kind==='confirmActivitiesSelect'){confirmActivitiesSelect();return}
  if(kind==='rdo-remove-extra'){const r=rdoSelected();if(r&&requirePerm('rdo','edit')){r.activities=r.activities.filter(x=>x.id!==id);persist();renderAll()}return}
  if(kind==='rdo-remove-paused'){const r=rdoSelected();if(r&&requirePerm('rdo','edit')){r.pausedActivities=r.pausedActivities.filter(x=>x.id!==id);persist();renderAll()}return}
  if(kind==='rdo-remove-event'){const r=rdoSelected(),domain=id,eventId=parts[2];if(r&&requirePerm('rdo','edit')){const key=domain==='safety'?'safetyEvents':'environmentEvents';r[key]=r[key].filter(x=>x.id!==eventId);persist();renderAll()}return}
  if(kind==='rdo-remove-photo'){const r=rdoSelected();if(r&&requirePerm('rdo','edit')){r.photos.splice(num(id),1);persist();renderAll()}return}
  if(kind==='approve-budget'){const a=D.budgetAdjustments.find(x=>x.id===id);if(a&&requirePerm('orcamento','approve')){const group=a.group||a.id,rows=D.budgetAdjustments.filter(x=>(x.group||x.id)===group),delta=sum(rows,x=>x.delta);if(['transferencia','reclassificacao'].includes(a.type)&&(rows.length<2||Math.abs(delta)>0.01))return toast('Transferência/reclassificação precisa ter origem e destino balanceados.');rows.forEach(x=>x.status='aprovada');audit('orcamento','ALTERACAO_APROVADA',group,money(delta));toast('Alteração aprovada.');renderAll()}}
  if(kind==='approve-cost'){const c=D.directCosts.find(x=>x.id===id);if(c&&requirePerm('custos','approve')){c.status='aprovado';audit('custos','CUSTO_APROVADO',c.id,money(c.amount));toast('Custo aprovado.');renderAll()}}
  if(kind==='approve-amendment'){const a=D.contractAmendments.find(x=>x.id===id);if(a&&requirePerm('contratos','approve')){a.status='aprovado';audit('contratos','ADITIVO_APROVADO',a.id,money(a.amount));toast('Aditivo aprovado e compromisso recalculado.');renderAll()}}
  if(kind==='approve-measurement'){const m=D.measurements.find(x=>x.id===id);if(m&&requirePerm('medicoes','approve')){const c=D.contracts.find(x=>x.id===m.contract),other=measuredContract(m.contract);if(!c||m.amount>contractValue(c)-other+0.01)return toast('Medição ultrapassa o saldo contratual disponível.');m.status='aprovada';audit('medicoes','MEDICAO_APROVADA',m.id,money(m.amount));toast('Medição aprovada.');renderAll()}}
  if(kind==='approve-invoice'){const n=D.invoices.find(x=>x.id===id);if(n&&requirePerm('nfs','approve')){n.status='aprovada';audit('nfs','NF_APROVADA',n.number,money(n.amount));toast('NF aprovada.');renderAll()}}
  if(kind==='pay-invoice'){const n=D.invoices.find(x=>x.id===id);if(!n)return toast('NF não encontrada.');if(n.status==='aprovada'&&can('custos','approve')){const paid=invoicePaidAmount(n.id),balance=n.amount-paid;if(balance<=0)return toast('NF já está quitada.');D.payments.push({id:uid('PG'),invoice:n.id,date:todayISO(),amount:balance,status:'pago'});n.status='paga';audit('custos','PAGAMENTO_REALIZADO',n.number,money(balance));toast('Pagamento registrado.');renderAll()}else if(!n.status==='aprovada')toast('Somente NF aprovada pode ser paga.');else toast('Seu perfil não tem permissão para pagar.');}
  if(kind==='complete-week'){const x=D.weeklyPlan.find(v=>v.id===id);if(x&&requirePerm('planejamento','edit')){x.actualQty=x.plannedQty;x.status='concluida';renderAll()}}
  if(kind==='complete-fortnight'){const x=D.fortnightPlan.find(v=>v.id===id);if(x&&requirePerm('planejamento','edit')){x.status='concluida';audit('planejamento','QUINZENAL_CONCLUIDA',x.id,x.activity);renderAll()}}
  if(kind==='resolve-restriction'){const r=D.restrictions.find(v=>v.id===id);if(r&&requirePerm('planejamento','edit')){r.status='concluida';renderAll()}}
  if(kind==='task-left'||kind==='task-right'){const t=D.tasks.find(x=>x.id===id);if(t&&requirePerm('tarefas','edit')){const order=['aberta','em_andamento','concluida'];let i=order.indexOf(t.status);i+=kind==='task-left'?-1:1;t.status=order[Math.max(0,Math.min(2,i))];renderAll()}}
  if(kind==='task-delete'){if(!requirePerm('tarefas','delete'))return;const i=D.tasks.findIndex(x=>x.id===id);if(i>=0&&confirm('Excluir esta tarefa da demonstração?')){D.tasks.splice(i,1);renderAll()}}
  if(kind==='topic-task'){const t=D.meetingTopics.find(x=>x.id===id);if(t&&requirePerm('tarefas','create')){D.tasks.push({id:uid('T'),subject:t.decision||t.title,owner:t.owner,due:todayISO(),priority:'media',status:'aberta',origin:'reuniao'});toast('Tarefa criada a partir da decisão.');renderAll()}}
  if(kind==='select-quote'){const q=D.purchaseQuotes.find(x=>x.id===id);if(q&&requirePerm('suprimentos','edit')){D.purchaseQuotes.filter(x=>x.request===q.request).forEach(x=>x.selected=false);q.selected=true;audit('suprimentos','COTACAO_SELECIONADA',q.id,q.supplier);renderAll()}}
  if(kind==='quote-order'){const q=D.purchaseQuotes.find(x=>x.id===id);if(q&&requirePerm('suprimentos','create')){const r=D.purchaseRequests.find(x=>x.id===q.request);const po={id:uid('PC'),number:'PC-'+String(D.purchaseOrders.length+1).padStart(3,'0'),request:r.id,supplier:q.supplier,wbs:r.wbs,cbs:r.cbs,description:r.description,amount:q.amount,status:'em_aprovacao',date:todayISO()};D.purchaseOrders.push(po);r.status='pedido_emitido';audit('suprimentos','PEDIDO_CRIADO',po.number,po.description);state.procurementTab='pedidos';renderAll()}}
  if(kind==='approve-po'){const po=D.purchaseOrders.find(x=>x.id===id);if(po&&requirePerm('suprimentos','approve')){po.status='aprovado';audit('suprimentos','PEDIDO_APROVADO',po.number,`Compromisso ${money(po.amount)}`);toast('Pedido aprovado e verba comprometida.');renderAll()}}
  if(kind==='receive-po'){const po=D.purchaseOrders.find(x=>x.id===id);if(po&&requirePerm('suprimentos','edit'))modalReceipt(po)}
}

function searchIndex(q){
  const s=q.toLowerCase();const hits=[];
  const add=(cond,cat,label,sub,page,ctx)=>{if(cond)hits.push({cat,label,sub:sub||'',page,ctx:ctx??null})};
  D.wbs.forEach(x=>add((x.code+' '+x.name).toLowerCase().includes(s),'EAP',`${x.code} ${x.name}`,'','wbs',x.id));
  D.contracts.forEach(x=>add((x.number+' '+x.name+' '+x.supplier).toLowerCase().includes(s),'Contrato',`${x.number} · ${x.name}`,x.supplier,'contratos',x.id));
  D.contractAmendments.forEach(x=>add((x.number+' '+x.description).toLowerCase().includes(s),'Aditivo',`Aditivo ${x.number}`,x.description,'contratos',x.contract));
  D.measurements.forEach(x=>add((x.id+' '+x.mes_referencia).toLowerCase().includes(s),'Medição',`Medição ${x.id}`,x.mes_referencia,'medicoes',x.contract));
  D.invoices.forEach(x=>add((x.number+' '+x.supplier+' '+x.categoria).toLowerCase().includes(s),'NF',`NF ${x.number} · ${x.supplier}`,x.categoria,'nfs',x.id));
  D.documents.forEach(x=>add((x.titulo+' '+x.categoria).toLowerCase().includes(s),'Documento',x.titulo,x.categoria,'documentos',x.id));
  D.tasks.forEach(x=>add((x.subject+' '+x.description).toLowerCase().includes(s),'Tarefa',x.subject,x.description,'tarefas',null));
  D.rdos.forEach(x=>add((x.number+' '+x.progress+' '+x.notes+' '+x.date).toLowerCase().includes(s),'RDO',`RDO ${x.number} · ${x.date}`,x.progress,'rdo',x.id));
  D.people.forEach(x=>add((x.name+' '+x.company+' '+x.function).toLowerCase().includes(s),'Pessoa',x.name,`${x.function} · ${x.company}`,'efetivo',null));
  D.equipment.forEach(x=>add((x.prefix+' '+x.type).toLowerCase().includes(s),'Equipamento',`${x.prefix} ${x.type}`,'','equipamentos',null));
  D.purchaseRequests.forEach(x=>add((x.number+' '+x.description).toLowerCase().includes(s),'Requisição',x.number,x.description,'suprimentos',null));
  D.purchaseOrders.forEach(x=>add((x.number+' '+x.description).toLowerCase().includes(s),'Pedido de compra',x.number,x.description,'suprimentos',null));
  D.occurrences.forEach(x=>add((x.description+' '+x.type).toLowerCase().includes(s),'Ocorrência',x.type,x.description,'ocorrencias',x.id));
  D.alerts.forEach(x=>add((x.title+' '+x.detail).toLowerCase().includes(s),'Alerta',x.title,x.detail,'alertas',null));
  D.meetings.forEach(x=>add((x.titulo+' '+x.local).toLowerCase().includes(s),'Reunião',x.titulo,x.local,'reunioes',x.id));
  D.mural.forEach(x=>add((x.texto+' '+x.autor).toLowerCase().includes(s),'Mural',x.texto,x.autor,'mural',null));
  D.cbs.forEach(x=>add((x.code+' '+x.name).toLowerCase().includes(s),'CBS',`${x.code} ${x.name}`,'','cadastro',null));
  D.activitiesCatalog.filter(x=>x.active).forEach(x=>add(x.description.toLowerCase().includes(s),'Atividade',x.description,'','cadastro',null));
  return hits.slice(0,30);
}
function renderSearchResults(q){
  const box=$('#searchResults');if(!box)return;
  if(q.length<2){box.innerHTML=empty('Digite ao menos 2 caracteres para buscar.');return}
  const hits=searchIndex(q);
  box.innerHTML=hits.length?hits.map((x,i)=>`<button class="search-hit" data-search-index="${i}"><b>${h(x.cat)}: ${h(x.label)}</b>${x.sub?`<div class="muted small">${h(x.sub)}</div>`:''}</button>`).join(''):empty('Nenhum resultado encontrado.');
  $$('#searchResults [data-search-index]').forEach(b=>b.onclick=()=>{const x=hits[num(b.dataset.searchIndex)];closeModal();navigate(x.page,x.ctx)});
}
function openGlobalSearch(){
  openModal('Busca global','<input id="searchInput" placeholder="Buscar EAP, contrato, documento, tarefa, RDO, pessoa, equipamento..." autocomplete="off"><div id="searchResults" class="search-results"></div>');
  const inp=$('#searchInput');
  inp.oninput=()=>renderSearchResults(inp.value.trim());
  inp.onkeydown=e=>{if(e.key==='Escape')closeModal();else if(e.key==='Enter'){const first=$('#searchResults .search-hit');if(first)first.click()}};
  renderSearchResults('');
  inp.focus();
}

